CREATE FUNCTION assistant.append_assistant_capability_event(p_execution_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_event_id uuid, p_event character varying, p_status character varying, p_payload jsonb DEFAULT '{}'::jsonb, p_dispatch_fence uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row assistant_capability_executions;
    v_existing_sequence BIGINT;
    v_sequence BIGINT;
BEGIN
    SELECT sequence INTO v_existing_sequence
      FROM assistant_capability_events
     WHERE execution_id = p_execution_id
       AND event_id = p_event_id
       AND tenant_id = p_tenant_id
       AND user_id = p_user_id
       AND session_id = p_session_id;
    IF FOUND THEN
        RETURN v_existing_sequence;
    END IF;

    SELECT * INTO v_row
      FROM assistant_capability_executions
     WHERE execution_id = p_execution_id
       AND tenant_id = p_tenant_id
       AND user_id = p_user_id
       AND session_id = p_session_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_row.status IN (
        'succeeded', 'failed', 'cancelled', 'timeout', 'side_effect_unknown'
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_TERMINAL_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;
    IF (p_status = 'published' AND v_row.last_event_sequence <> 0)
       OR (p_status = 'dispatched' AND v_row.status NOT IN (
           'published', 'dispatched', 'running'))
       OR (p_status = 'running' AND v_row.status NOT IN ('dispatched', 'running'))
    THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_EVENT_INVALID'
            USING ERRCODE = '22023';
    END IF;
    IF p_dispatch_fence IS NOT NULL
       AND v_row.dispatch_fence IS DISTINCT FROM p_dispatch_fence
    THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_DISPATCH_FENCE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF p_status IN ('dispatched', 'running') AND v_row.dispatch_fence IS NULL THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_DISPATCH_REQUIRED'
            USING ERRCODE = '42501';
    END IF;
    IF p_status IN ('succeeded', 'timeout', 'side_effect_unknown')
       AND v_row.dispatch_fence IS NULL
    THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_DISPATCH_REQUIRED'
            USING ERRCODE = '42501';
    END IF;

    v_sequence := v_row.last_event_sequence + 1;
    INSERT INTO assistant_capability_events (
        execution_id, sequence, event_id, tenant_id, user_id, session_id,
        run_id, tool_call_id, attempt_id, event, status, payload
    ) VALUES (
        p_execution_id, v_sequence, p_event_id, v_row.tenant_id,
        v_row.user_id, v_row.session_id, v_row.run_id, v_row.tool_call_id,
        v_row.attempt_id, p_event, p_status, p_payload
    );

    UPDATE assistant_capability_executions
       SET last_event_sequence = v_sequence,
           status = p_status,
           result_summary = CASE
               WHEN p_status IN (
                   'succeeded', 'failed', 'cancelled', 'timeout',
                   'side_effect_unknown'
               ) THEN p_payload->'result'
               ELSE result_summary
           END,
           error_code = CASE
               WHEN p_status IN ('failed', 'cancelled', 'timeout', 'side_effect_unknown')
               THEN NULLIF(p_payload->>'error_code', '')
               ELSE error_code
           END,
           terminal_at = CASE
               WHEN p_status IN (
                   'succeeded', 'failed', 'cancelled', 'timeout',
                   'side_effect_unknown'
               ) THEN NOW()
               ELSE NULL
           END,
           worker_lease_until = CASE
               WHEN p_status = 'running' THEN NOW() + INTERVAL '30 seconds'
               WHEN p_status IN (
                   'succeeded', 'failed', 'cancelled', 'timeout',
                   'side_effect_unknown'
               ) THEN NULL
               ELSE worker_lease_until
           END,
           updated_at = NOW()
     WHERE execution_id = p_execution_id;
    RETURN v_sequence;
EXCEPTION WHEN unique_violation THEN
    SELECT sequence INTO v_existing_sequence
      FROM assistant_capability_events
     WHERE execution_id = p_execution_id
       AND event_id = p_event_id
       AND tenant_id = p_tenant_id
       AND user_id = p_user_id
       AND session_id = p_session_id;
    IF FOUND THEN
        RETURN v_existing_sequence;
    END IF;
    RAISE;
END;
$$;

CREATE FUNCTION assistant.append_assistant_runtime_item(p_runtime_thread_id uuid, p_kernel_thread_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_event_id uuid, p_event_key character varying, p_turn_id character varying, p_item_id character varying, p_event_type character varying, p_item_type character varying, p_status character varying, p_payload jsonb, p_payload_sha256 character) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    existing_sequence BIGINT;
    next_sequence BIGINT;
BEGIN
    PERFORM 1
    FROM assistant_runtime_threads
    WHERE runtime_thread_id = p_runtime_thread_id
      AND tenant_id = p_tenant_id
      AND user_id = p_user_id
      AND session_id = p_session_id
      AND kernel_owner = 'agent_runtime'
      AND archived_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_THREAD_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM assistant_runtime_thread_members
        WHERE kernel_thread_id = p_kernel_thread_id
          AND runtime_thread_id = p_runtime_thread_id
          AND tenant_id = p_tenant_id
          AND user_id = p_user_id
          AND session_id = p_session_id
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_MEMBER_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    SELECT sequence INTO existing_sequence
    FROM assistant_runtime_items
    WHERE runtime_thread_id = p_runtime_thread_id
      AND event_key = p_event_key;

    IF existing_sequence IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM assistant_runtime_items
            WHERE runtime_thread_id = p_runtime_thread_id
              AND event_key = p_event_key
              AND kernel_thread_id = p_kernel_thread_id
              AND event_id = p_event_id
              AND payload_sha256 = p_payload_sha256
        ) THEN
            RAISE EXCEPTION 'ASSISTANT_RUNTIME_EVENT_KEY_CONFLICT'
                USING ERRCODE = '23505';
        END IF;
        RETURN existing_sequence;
    END IF;

    UPDATE assistant_runtime_threads
    SET last_sequence = last_sequence + 1,
        updated_at = NOW()
    WHERE runtime_thread_id = p_runtime_thread_id
    RETURNING last_sequence INTO next_sequence;

    INSERT INTO assistant_runtime_items (
        runtime_thread_id, kernel_thread_id, sequence,
        event_id, event_key, turn_id, item_id,
        event_type, item_type, status, payload, payload_sha256,
        tenant_id, user_id, session_id
    ) VALUES (
        p_runtime_thread_id, p_kernel_thread_id, next_sequence,
        p_event_id, p_event_key,
        p_turn_id, p_item_id, p_event_type, p_item_type, p_status,
        p_payload, p_payload_sha256, p_tenant_id, p_user_id, p_session_id
    );

    RETURN next_sequence;
END;
$$;

