CREATE FUNCTION assistant.complete_assistant_runtime_model_call(p_call_id uuid, p_input_tokens bigint, p_output_tokens bigint, p_cost_microusd bigint, p_provider_request_id character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_lease_id UUID;
BEGIN
    UPDATE assistant_runtime_model_calls
       SET status = 'completed', input_tokens = p_input_tokens,
           output_tokens = p_output_tokens, cost_microusd = p_cost_microusd,
           provider_request_id = p_provider_request_id,
           completed_at = NOW(), updated_at = NOW()
     WHERE call_id = p_call_id AND status = 'dispatched'
     RETURNING lease_id INTO v_lease_id;
    IF v_lease_id IS NULL THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_MODEL_CALL_NOT_DISPATCHED'
            USING ERRCODE = '55000';
    END IF;
    UPDATE assistant_runtime_model_leases
       SET calls_completed = calls_completed + 1,
           used_input_tokens = used_input_tokens + p_input_tokens,
           used_output_tokens = used_output_tokens + p_output_tokens,
           used_cost_microusd = used_cost_microusd + p_cost_microusd,
           updated_at = NOW()
     WHERE lease_id = v_lease_id;
END;
$$;

CREATE FUNCTION assistant.dispatch_assistant_capability_execution(p_execution_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_dispatch_fence uuid, p_lease_ms bigint DEFAULT 30000) RETURNS TABLE(dispatch_fence uuid, claimed boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row assistant_capability_executions;
    v_approval assistant_tool_approvals%ROWTYPE;
BEGIN
    SELECT * INTO v_row
      FROM assistant_capability_executions
     WHERE execution_id = p_execution_id
       AND tenant_id = p_tenant_id
       AND user_id = p_user_id
       AND session_id = p_session_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF v_row.status IN (
        'succeeded', 'failed', 'cancelled', 'timeout', 'side_effect_unknown'
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_TERMINAL_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;
    IF v_row.dispatch_fence IS NOT NULL THEN
        -- A read can be recovered safely after a worker process loss. A
        -- write/unknown dispatch can only be reconciled by its execution
        -- receipt and must never be blindly repeated.
        IF v_row.effect <> 'read' THEN
            IF v_row.dispatch_fence IS DISTINCT FROM p_dispatch_fence THEN
                RAISE EXCEPTION 'ASSISTANT_CAPABILITY_DISPATCH_FENCE_MISMATCH'
                    USING ERRCODE = '42501';
            END IF;
            RETURN QUERY SELECT v_row.dispatch_fence, FALSE;
            RETURN;
        END IF;
        IF v_row.worker_lease_until IS NOT NULL
           AND v_row.worker_lease_until > NOW()
        THEN
            RETURN QUERY SELECT v_row.dispatch_fence, FALSE;
            RETURN;
        END IF;
        UPDATE assistant_capability_executions
           SET dispatch_fence = p_dispatch_fence,
               worker_lease_until = NOW() + make_interval(secs => (LEAST(GREATEST(p_lease_ms, 1000), 120000)::double precision / 1000.0)),
               updated_at = NOW()
         WHERE execution_id = p_execution_id;
        RETURN QUERY SELECT p_dispatch_fence, TRUE;
        RETURN;
    END IF;

    IF v_row.effect IN ('write', 'unknown') THEN
        SELECT * INTO v_approval
          FROM assistant_tool_approvals
         WHERE approval_id = v_row.approval_id
           AND tenant_id = v_row.tenant_id
           AND user_id = v_row.user_id
           AND session_id = v_row.session_id
           AND run_id = v_row.run_id
           AND tool_call_id = v_row.tool_call_id
           AND tool_name = v_row.capability_id
           AND status = 'approved'
           AND expires_at > NOW()
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'ASSISTANT_CAPABILITY_APPROVAL_REQUIRED'
                USING ERRCODE = '42501';
        END IF;
        IF v_approval.arguments IS DISTINCT FROM v_row.arguments THEN
            RAISE EXCEPTION 'ASSISTANT_CAPABILITY_APPROVAL_ARGUMENT_MISMATCH'
                USING ERRCODE = '42501';
        END IF;
        UPDATE assistant_tool_approvals
           SET status = 'consumed', updated_at = NOW()
         WHERE approval_id = v_row.approval_id
           AND status = 'approved';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'ASSISTANT_CAPABILITY_APPROVAL_REPLAYED'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE assistant_capability_executions
       SET dispatch_fence = p_dispatch_fence,
           dispatched_at = NOW(),
           approval_status = CASE
               WHEN effect = 'read' THEN approval_status ELSE 'consumed' END,
           status = 'dispatched',
           worker_lease_until = NOW() + make_interval(secs => (LEAST(GREATEST(p_lease_ms, 1000), 120000)::double precision / 1000.0)),
           updated_at = NOW()
     WHERE execution_id = p_execution_id;
    RETURN QUERY SELECT p_dispatch_fence, TRUE;
END;
$$;

CREATE FUNCTION assistant.ensure_assistant_runtime_thread(p_runtime_thread_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_source_kind character varying DEFAULT 'native'::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_source_kind NOT IN ('native', 'legacy_import') THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_SOURCE_KIND_INVALID'
            USING ERRCODE = '22023';
    END IF;

    INSERT INTO assistant_runtime_threads (
        runtime_thread_id, tenant_id, user_id, session_id,
        kernel_owner, source_kind, import_status
    ) VALUES (
        p_runtime_thread_id, p_tenant_id, p_user_id, p_session_id,
        'agent_runtime', p_source_kind,
        CASE WHEN p_source_kind = 'legacy_import' THEN 'pending' ELSE 'not_required' END
    ) ON CONFLICT (tenant_id, user_id, session_id) DO NOTHING;

    IF NOT EXISTS (
        SELECT 1 FROM assistant_runtime_threads
         WHERE runtime_thread_id = p_runtime_thread_id
           AND tenant_id = p_tenant_id AND user_id = p_user_id
           AND session_id = p_session_id AND kernel_owner = 'agent_runtime'
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_THREAD_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO assistant_runtime_thread_members (
        kernel_thread_id, runtime_thread_id, kernel_session_id,
        relation_kind, tenant_id, user_id, session_id
    ) VALUES (
        p_runtime_thread_id, p_runtime_thread_id, p_runtime_thread_id,
        'root', p_tenant_id, p_user_id, p_session_id
    ) ON CONFLICT (kernel_thread_id) DO NOTHING;
END;
$$;

CREATE FUNCTION assistant.import_assistant_legacy_session(p_runtime_thread_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying) RETURNS TABLE(import_status character varying, source_history_count integer, source_history_sha256 character)
    LANGUAGE plpgsql
    SET search_path TO 'gateway', 'assistant', 'knowledge', 'public'
    AS $_$
DECLARE
    v_sessions_table REGCLASS;
    v_runs_table REGCLASS;
    v_commands_table REGCLASS;
    v_approvals_table REGCLASS;
    v_session_row JSONB;
    v_history JSONB;
    v_message JSONB;
    v_metadata JSONB;
    v_tool_calls JSONB;
    v_tool_results JSONB;
    v_tool_call JSONB;
    v_tool_result JSONB;
    v_approval JSONB;
    v_index INTEGER;
    v_tool_index INTEGER;
    v_count INTEGER;
    v_rollout_count INTEGER := 0;
    v_tool_call_count INTEGER := 0;
    v_approval_count INTEGER := 0;
    v_hash CHAR(64);
    v_stored_count INTEGER;
    v_stored_hash CHAR(64);
    v_thread_status VARCHAR(32);
    v_role TEXT;
    v_content TEXT;
    v_call_id TEXT;
    v_tool_name TEXT;
    v_arguments JSONB;
    v_arguments_text TEXT;
    v_output_text TEXT;
    v_seen_call_ids TEXT[] := ARRAY[]::TEXT[];
    v_message_call_ids TEXT[] := ARRAY[]::TEXT[];
    v_payload JSONB;
    v_event_id UUID;
    v_event_key VARCHAR(255);
    v_event_prefix TEXT;
    v_in_flight BOOLEAN := FALSE;
BEGIN
    -- Prefer the authoritative split-schema tables.  The unqualified fallback
    -- keeps isolated single-schema migration contracts representative.
    -- A test or embedded deployment may intentionally install the function in
    -- its own first search_path schema while an unrelated assistant schema is
    -- present in the same database.  Only the production gateway-owned
    -- function crosses into assistant.* explicitly.
    v_sessions_table := CASE WHEN current_schema() = 'gateway'
        THEN COALESCE(to_regclass('assistant.sessions'), to_regclass('sessions'))
        ELSE to_regclass('sessions') END;
    v_runs_table := CASE WHEN current_schema() = 'gateway'
        THEN COALESCE(to_regclass('assistant.assistant_runs'), to_regclass('assistant_runs'))
        ELSE to_regclass('assistant_runs') END;
    v_commands_table := CASE WHEN current_schema() = 'gateway'
        THEN COALESCE(to_regclass('assistant.assistant_command_queue'), to_regclass('assistant_command_queue'))
        ELSE to_regclass('assistant_command_queue') END;
    v_approvals_table := CASE WHEN current_schema() = 'gateway'
        THEN COALESCE(to_regclass('assistant.assistant_tool_approvals'), to_regclass('assistant_tool_approvals'))
        ELSE to_regclass('assistant_tool_approvals') END;

    IF v_sessions_table IS NULL THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_SESSION_STORAGE_UNAVAILABLE'
            USING ERRCODE = '55000';
    END IF;

    EXECUTE format(
        'SELECT jsonb_build_object(''history'', COALESCE(history, ''[]''::jsonb)) '
        'FROM %s WHERE session_id = $1 AND tenant_id = $2 AND user_id = $3 FOR UPDATE',
        v_sessions_table
    )
    INTO v_session_row
    USING p_session_id, p_tenant_id, p_user_id;

    IF v_session_row IS NULL THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_SESSION_NOT_FOUND' USING ERRCODE = '42501';
    END IF;

    IF v_runs_table IS NOT NULL THEN
        EXECUTE format(
            'SELECT EXISTS (SELECT 1 FROM %s '
            'WHERE tenant_id = $1 AND user_id = $2 AND session_id = $3 '
            'AND status IN (''running'', ''blocked'', ''awaiting_approval'', ''approval_claimed'', '
            '''side_effect_unknown'', ''terminal_persistence_unknown''))',
            v_runs_table
        )
        INTO v_in_flight
        USING p_tenant_id, p_user_id, p_session_id;
    END IF;

    IF NOT v_in_flight AND v_commands_table IS NOT NULL THEN
        EXECUTE format(
            'SELECT EXISTS (SELECT 1 FROM %s '
            'WHERE tenant_id = $1 AND user_id = $2 AND session_id = $3 '
            'AND status IN (''queued'', ''running'', ''awaiting_approval'', '
            '''approval_claimed'', ''side_effect_unknown''))',
            v_commands_table
        )
        INTO v_in_flight
        USING p_tenant_id, p_user_id, p_session_id;
    END IF;

    IF NOT v_in_flight AND v_approvals_table IS NOT NULL THEN
        EXECUTE format(
            'SELECT EXISTS (SELECT 1 FROM %s '
            'WHERE tenant_id = $1 AND user_id = $2 AND session_id = $3 '
            'AND status IN (''pending'', ''claimed'', ''approved''))',
            v_approvals_table
        )
        INTO v_in_flight
        USING p_tenant_id, p_user_id, p_session_id;
    END IF;

    IF v_in_flight THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_IN_FLIGHT' USING ERRCODE = '55000';
    END IF;

    v_history := v_session_row->'history';
    v_history := CASE WHEN jsonb_typeof(v_history) = 'array' THEN v_history ELSE '[]'::jsonb END;
    v_count := jsonb_array_length(v_history);
    v_hash := encode(digest(v_history::text, 'sha256'), 'hex')::CHAR(64);
    v_event_prefix := 'legacy:' || md5(p_session_id);

    PERFORM ensure_assistant_runtime_thread(
        p_runtime_thread_id, p_tenant_id, p_user_id, p_session_id, 'legacy_import'
    );

    SELECT t.import_status, t.source_history_count, t.source_history_sha256
      INTO v_thread_status, v_stored_count, v_stored_hash
      FROM assistant_runtime_threads t
     WHERE t.runtime_thread_id = p_runtime_thread_id
       AND t.tenant_id = p_tenant_id AND t.user_id = p_user_id
       AND t.session_id = p_session_id
     FOR UPDATE;
    IF v_thread_status = 'ready' THEN
        IF v_stored_count <> v_count OR v_stored_hash IS DISTINCT FROM v_hash THEN
            RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_SOURCE_CHANGED'
                USING ERRCODE = '55000';
        END IF;
        RETURN QUERY SELECT v_thread_status, v_stored_count, v_stored_hash;
        RETURN;
    END IF;
    IF v_thread_status = 'importing' THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_IN_FLIGHT' USING ERRCODE = '55000';
    END IF;

    UPDATE assistant_runtime_threads
       SET import_status = 'importing', source_kind = 'legacy_import'
     WHERE runtime_thread_id = p_runtime_thread_id;

    FOR v_message, v_index IN
        SELECT value, ordinality::INTEGER
          FROM jsonb_array_elements(v_history) WITH ORDINALITY
    LOOP
        IF jsonb_typeof(v_message) <> 'object' THEN
            v_message := jsonb_build_object('role', 'user', 'content', v_message);
        END IF;
        v_role := COALESCE(NULLIF(v_message->>'role', ''), 'user');
        IF v_role NOT IN ('user', 'assistant') THEN
            RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_ROLE_INVALID'
                USING ERRCODE = '22023';
        END IF;
        v_content := CASE
            WHEN v_message->'content' IS NULL OR v_message->'content' = 'null'::jsonb THEN ''
            WHEN jsonb_typeof(v_message->'content') = 'string' THEN v_message->>'content'
            ELSE (v_message->'content')::text
        END;
        v_metadata := CASE
            WHEN jsonb_typeof(v_message->'metadata') = 'object' THEN v_message->'metadata'
            ELSE '{}'::jsonb
        END;
        v_tool_calls := CASE
            WHEN jsonb_typeof(v_metadata->'tool_calls') = 'array' THEN v_metadata->'tool_calls'
            ELSE '[]'::jsonb
        END;
        v_tool_results := CASE
            WHEN jsonb_typeof(v_metadata->'tool_results') = 'array' THEN v_metadata->'tool_results'
            ELSE '[]'::jsonb
        END;
        v_message_call_ids := ARRAY[]::TEXT[];

        IF v_role <> 'assistant'
           AND (jsonb_array_length(v_tool_calls) > 0 OR jsonb_array_length(v_tool_results) > 0) THEN
            RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                USING ERRCODE = '22023';
        END IF;

        IF v_role = 'assistant' THEN
            FOR v_tool_call, v_tool_index IN
                SELECT value, ordinality::INTEGER
                  FROM jsonb_array_elements(v_tool_calls) WITH ORDINALITY
            LOOP
                IF jsonb_typeof(v_tool_call) <> 'object' THEN
                    RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                        USING ERRCODE = '22023';
                END IF;
                v_call_id := NULLIF(v_tool_call->>'id', '');
                v_tool_name := NULLIF(v_tool_call->>'name', '');
                IF v_call_id IS NULL OR v_tool_name IS NULL OR v_call_id = ANY(v_seen_call_ids) THEN
                    RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                        USING ERRCODE = '22023';
                END IF;
                IF (
                    SELECT count(*) FROM jsonb_array_elements(v_tool_calls) AS call
                    WHERE call->>'id' = v_call_id
                ) <> 1 OR (
                    SELECT count(*) FROM jsonb_array_elements(v_tool_results) AS result
                    WHERE result->>'tool_call_id' = v_call_id
                ) <> 1 THEN
                    RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                        USING ERRCODE = '22023';
                END IF;
                SELECT value INTO v_tool_result
                  FROM jsonb_array_elements(v_tool_results)
                 WHERE value->>'tool_call_id' = v_call_id;
                IF jsonb_typeof(v_tool_result) <> 'object' THEN
                    RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                        USING ERRCODE = '22023';
                END IF;

                v_arguments := COALESCE(v_tool_call->'arguments', '{}'::jsonb);
                IF jsonb_typeof(v_arguments) <> 'object' THEN
                    RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_ARGUMENTS_INVALID'
                        USING ERRCODE = '22023';
                END IF;
                v_arguments_text := v_arguments::text;
                v_seen_call_ids := array_append(v_seen_call_ids, v_call_id);
                v_message_call_ids := array_append(v_message_call_ids, v_call_id);

                v_payload := jsonb_build_object(
                    'type', 'response_item',
                    'payload', jsonb_build_object(
                        'type', 'function_call',
                        'name', v_tool_name,
                        'arguments', v_arguments_text,
                        'call_id', v_call_id
                    )
                );
                v_event_key := v_event_prefix || ':' || v_index::TEXT
                    || ':tool:' || v_tool_index::TEXT || ':call';
                v_event_id := md5(v_event_key)::UUID;
                PERFORM append_assistant_runtime_item(
                    p_runtime_thread_id, p_runtime_thread_id,
                    p_tenant_id, p_user_id, p_session_id,
                    v_event_id, v_event_key, 'legacy-' || v_index::TEXT,
                    v_call_id, 'rollout/item', 'function_call', 'completed',
                    v_payload, encode(digest(v_payload::text, 'sha256'), 'hex')::CHAR(64)
                );
                v_rollout_count := v_rollout_count + 1;

                v_output_text := CASE
                    WHEN NULLIF(v_tool_result->>'error', '') IS NOT NULL THEN
                        jsonb_build_object(
                            'status', COALESCE(v_tool_result->>'status', 'error'),
                            'result', v_tool_result->'result',
                            'error', v_tool_result->>'error'
                        )::text
                    WHEN v_tool_result->'result' IS NULL
                         OR v_tool_result->'result' = 'null'::jsonb THEN 'null'
                    WHEN jsonb_typeof(v_tool_result->'result') = 'string' THEN
                        v_tool_result->>'result'
                    ELSE (v_tool_result->'result')::text
                END;
                v_payload := jsonb_build_object(
                    'type', 'response_item',
                    'payload', jsonb_build_object(
                        'type', 'function_call_output',
                        'call_id', v_call_id,
                        'name', v_tool_name,
                        'output', v_output_text
                    )
                );
                v_event_key := v_event_prefix || ':' || v_index::TEXT
                    || ':tool:' || v_tool_index::TEXT || ':result';
                v_event_id := md5(v_event_key)::UUID;
                PERFORM append_assistant_runtime_item(
                    p_runtime_thread_id, p_runtime_thread_id,
                    p_tenant_id, p_user_id, p_session_id,
                    v_event_id, v_event_key, 'legacy-' || v_index::TEXT,
                    v_call_id, 'rollout/item', 'function_call_output', 'completed',
                    v_payload, encode(digest(v_payload::text, 'sha256'), 'hex')::CHAR(64)
                );
                v_rollout_count := v_rollout_count + 1;
                v_tool_call_count := v_tool_call_count + 1;
            END LOOP;

            IF EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_tool_results) AS result
                WHERE NULLIF(result->>'tool_call_id', '') IS NULL
                   OR NOT (result->>'tool_call_id' = ANY(v_message_call_ids))
            ) THEN
                RAISE EXCEPTION 'ASSISTANT_RUNTIME_IMPORT_TOOL_PAIRING_INVALID'
                    USING ERRCODE = '22023';
            END IF;
        END IF;

        -- Empty Assistant messages that only carried tool activity are not
        -- valid model inputs and add no information after the paired items.
        IF v_role = 'user' OR v_content <> '' THEN
            v_payload := jsonb_build_object(
                'type', 'response_item',
                'payload', jsonb_build_object(
                    'type', 'message',
                    'role', v_role,
                    'content', jsonb_build_array(
                        jsonb_build_object(
                            'type', CASE WHEN v_role = 'assistant'
                                         THEN 'output_text' ELSE 'input_text' END,
                            'text', v_content
                        )
                    )
                )
            );
            v_event_key := v_event_prefix || ':' || v_index::TEXT || ':message';
            v_event_id := md5(v_event_key)::UUID;
            PERFORM append_assistant_runtime_item(
                p_runtime_thread_id, p_runtime_thread_id,
                p_tenant_id, p_user_id, p_session_id,
                v_event_id, v_event_key, 'legacy-' || v_index::TEXT,
                'legacy-' || v_index::TEXT, 'rollout/item', 'message', 'completed',
                v_payload, encode(digest(v_payload::text, 'sha256'), 'hex')::CHAR(64)
            );
            v_rollout_count := v_rollout_count + 1;
        END IF;
    END LOOP;

    -- Preserve terminal approval provenance without replaying approval state or
    -- copying raw arguments into the model-visible history.
    IF v_approvals_table IS NOT NULL THEN
        FOR v_approval IN EXECUTE format(
            'SELECT to_jsonb(a) FROM %s a '
            'WHERE tenant_id = $1 AND user_id = $2 AND session_id = $3 '
            'AND status NOT IN (''pending'', ''claimed'', ''approved'') '
            'ORDER BY created_at, approval_id',
            v_approvals_table
        ) USING p_tenant_id, p_user_id, p_session_id
        LOOP
            v_payload := jsonb_build_object(
                'schema_version', 'agent-runtime-legacy-approval/v1',
                'approval_id', v_approval->>'approval_id',
                'run_id', v_approval->>'run_id',
                'tool_name', v_approval->>'tool_name',
                'status', v_approval->>'status',
                'reason', v_approval->>'reason',
                'approved_by', v_approval->>'approved_by',
                'approved_at', v_approval->>'approved_at',
                'expires_at', v_approval->>'expires_at',
                'arguments_sha256', encode(
                    digest(COALESCE(v_approval->'arguments', '{}'::jsonb)::text, 'sha256'),
                    'hex'
                )
            );
            v_event_key := v_event_prefix || ':approval:' || (v_approval->>'approval_id');
            v_event_id := md5(v_event_key)::UUID;
            PERFORM append_assistant_runtime_item(
                p_runtime_thread_id, p_runtime_thread_id,
                p_tenant_id, p_user_id, p_session_id,
                v_event_id, v_event_key, v_approval->>'run_id',
                v_approval->>'approval_id', 'agent-runtime/legacy_approval', 'approval',
                v_approval->>'status', v_payload,
                encode(digest(v_payload::text, 'sha256'), 'hex')::CHAR(64)
            );
            v_approval_count := v_approval_count + 1;
        END LOOP;
    END IF;

    INSERT INTO assistant_runtime_thread_projections (
        kernel_thread_id, runtime_thread_id, tenant_id, user_id, session_id, projection
    ) VALUES (
        p_runtime_thread_id, p_runtime_thread_id, p_tenant_id, p_user_id, p_session_id,
        jsonb_build_object(
            'legacy_import', jsonb_build_object(
                'schema_version', 'assistant-turn-contract/v1',
                'normalizer_version', 2,
                'source', 'legacy_session_history',
                'history_count', v_count,
                'history_sha256', v_hash,
                'rollout_item_count', v_rollout_count,
                'tool_call_count', v_tool_call_count,
                'approval_receipt_count', v_approval_count
            )
        )
    ) ON CONFLICT (kernel_thread_id) DO UPDATE
        SET projection = assistant_runtime_thread_projections.projection
            || EXCLUDED.projection,
            updated_at = NOW();

    UPDATE assistant_runtime_threads
       SET import_status = 'ready', imported_at = NOW(),
           source_history_count = v_count, source_history_sha256 = v_hash,
           import_error_code = NULL
     WHERE runtime_thread_id = p_runtime_thread_id;

    RETURN QUERY SELECT 'ready'::VARCHAR, v_count, v_hash;
END;
$_$;

CREATE FUNCTION assistant.issue_assistant_runtime_turn(p_snapshot_id uuid, p_lease_id uuid, p_run_id uuid, p_runtime_thread_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_kernel_revision character varying, p_snapshot_schema_version character varying, p_snapshot jsonb, p_snapshot_sha256 character, p_capability_revision bigint, p_selected_reasoning_option character varying, p_lease_schema_version character varying, p_provider_id character varying, p_model_id character varying, p_provider_revision character varying, p_nonce_sha256 character, p_max_calls integer, p_max_input_tokens bigint, p_max_output_tokens bigint, p_max_cost_microusd bigint, p_expires_at timestamp with time zone, p_request_preview text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_owner VARCHAR(32);
    v_kernel_revision VARCHAR(100);
BEGIN
    SELECT runtime_owner, kernel_revision
      INTO v_owner, v_kernel_revision
      FROM assistant_session_runtime_assignments
     WHERE tenant_id = p_tenant_id
       AND user_id = p_user_id
       AND session_id = p_session_id
     FOR SHARE;
    IF v_owner IS DISTINCT FROM 'agent_runtime'
       OR v_kernel_revision IS DISTINCT FROM p_kernel_revision THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_ASSIGNMENT_MISMATCH'
            USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM assistant_runtime_threads
         WHERE runtime_thread_id = p_runtime_thread_id
           AND tenant_id = p_tenant_id
           AND user_id = p_user_id
           AND session_id = p_session_id
           AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_THREAD_SCOPE_MISMATCH'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO assistant_runtime_snapshots (
        snapshot_id, runtime_thread_id, run_id, tenant_id, user_id,
        session_id, schema_version, capability_revision,
        selected_reasoning_option, snapshot, snapshot_sha256, expires_at
    ) VALUES (
        p_snapshot_id, p_runtime_thread_id, p_run_id, p_tenant_id, p_user_id,
        p_session_id, p_snapshot_schema_version, p_capability_revision,
        p_selected_reasoning_option, p_snapshot, p_snapshot_sha256, p_expires_at
    );

    INSERT INTO assistant_runs (
        run_id, tenant_id, user_id, session_id, status, engine,
        execution_profile, memory_mode, os_agent_enabled, request_preview,
        harness_thread_id, harness_turn_id, runtime_snapshot_id,
        kernel_revision, capability_revision
    ) VALUES (
        p_run_id, p_tenant_id, p_user_id, p_session_id, 'running',
        'agent_runtime', 'safe', 'off', FALSE, LEFT(p_request_preview, 500),
        p_runtime_thread_id, p_run_id::text, p_snapshot_id,
        p_kernel_revision, p_capability_revision
    );

    INSERT INTO assistant_runtime_model_leases (
        lease_id, snapshot_id, run_id, runtime_thread_id, tenant_id,
        user_id, session_id, schema_version, provider_id, model_id,
        provider_revision, capability_revision, nonce_sha256, max_calls,
        max_input_tokens, max_output_tokens, max_cost_microusd, expires_at
    ) VALUES (
        p_lease_id, p_snapshot_id, p_run_id, p_runtime_thread_id, p_tenant_id,
        p_user_id, p_session_id, p_lease_schema_version, p_provider_id,
        p_model_id, p_provider_revision, p_capability_revision,
        p_nonce_sha256, p_max_calls, p_max_input_tokens, p_max_output_tokens,
        p_max_cost_microusd, p_expires_at
    );
END;
$$;

CREATE TABLE assistant.assistant_capability_executions (
    execution_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    tenant_id character varying(64) NOT NULL,
    user_id character varying(64) NOT NULL,
    session_id character varying(100) NOT NULL,
    run_id uuid NOT NULL,
    tool_call_id character varying(160) NOT NULL,
    attempt_id character varying(160) NOT NULL,
    capability_id character varying(160) NOT NULL,
    capability_revision bigint NOT NULL,
    arguments jsonb NOT NULL,
    arguments_sha256 character(64) NOT NULL,
    idempotency_key character varying(160) NOT NULL,
    effect character varying(16) NOT NULL,
    approval_policy character varying(16) NOT NULL,
    approval_id uuid,
    approval_status character varying(20) DEFAULT 'not_required'::character varying NOT NULL,
    resource_binding jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(32) DEFAULT 'published'::character varying NOT NULL,
    events_url text NOT NULL,
    dispatch_fence uuid,
    dispatched_at timestamp with time zone,
    result_summary jsonb,
    error_code character varying(100),
    terminal_at timestamp with time zone,
    last_event_sequence bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    worker_lease_until timestamp with time zone,
    CONSTRAINT assistant_capability_executions_approval_policy_check CHECK (((approval_policy)::text = ANY (ARRAY[('never'::character varying)::text, ('on_request'::character varying)::text, ('always'::character varying)::text]))),
    CONSTRAINT assistant_capability_executions_approval_shape_check CHECK (((((effect)::text = 'read'::text) AND (approval_id IS NULL) AND ((approval_status)::text = 'not_required'::text)) OR (((effect)::text = ANY (ARRAY[('write'::character varying)::text, ('unknown'::character varying)::text])) AND (approval_id IS NOT NULL) AND ((approval_status)::text <> 'not_required'::text)))),
    CONSTRAINT assistant_capability_executions_approval_status_check CHECK (((approval_status)::text = ANY (ARRAY[('not_required'::character varying)::text, ('pending'::character varying)::text, ('approved'::character varying)::text, ('consumed'::character varying)::text, ('denied'::character varying)::text, ('expired'::character varying)::text]))),
    CONSTRAINT assistant_capability_executions_arguments_object_check CHECK ((jsonb_typeof(arguments) = 'object'::text)),
    CONSTRAINT assistant_capability_executions_capability_revision_check CHECK ((capability_revision >= 1)),
    CONSTRAINT assistant_capability_executions_dispatch_shape_check CHECK ((((dispatch_fence IS NULL) AND (dispatched_at IS NULL)) OR ((dispatch_fence IS NOT NULL) AND (dispatched_at IS NOT NULL)))),
    CONSTRAINT assistant_capability_executions_effect_check CHECK (((effect)::text = ANY (ARRAY[('read'::character varying)::text, ('write'::character varying)::text, ('unknown'::character varying)::text]))),
    CONSTRAINT assistant_capability_executions_events_url_check CHECK ((events_url ~ '^/internal/v2/capabilities/executions/[0-9a-f-]+/events$'::text)),
    CONSTRAINT assistant_capability_executions_hash_check CHECK ((arguments_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT assistant_capability_executions_last_event_sequence_check CHECK ((last_event_sequence >= 0)),
    CONSTRAINT assistant_capability_executions_resource_binding_object_check CHECK ((jsonb_typeof(resource_binding) = 'object'::text)),
    CONSTRAINT assistant_capability_executions_status_check CHECK (((status)::text = ANY (ARRAY[('published'::character varying)::text, ('awaiting_approval'::character varying)::text, ('dispatched'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('timeout'::character varying)::text, ('side_effect_unknown'::character varying)::text]))),
    CONSTRAINT assistant_capability_executions_terminal_shape_check CHECK (((((status)::text = ANY (ARRAY[('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('timeout'::character varying)::text, ('side_effect_unknown'::character varying)::text])) AND (terminal_at IS NOT NULL)) OR (((status)::text <> ALL (ARRAY[('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('timeout'::character varying)::text, ('side_effect_unknown'::character varying)::text])) AND (terminal_at IS NULL))))
);

CREATE FUNCTION assistant.reserve_assistant_capability_execution(p_execution_id uuid, p_lease_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_run_id uuid, p_tool_call_id character varying, p_attempt_id character varying, p_capability_id character varying, p_capability_revision bigint, p_arguments jsonb, p_arguments_sha256 character, p_idempotency_key character varying, p_effect character varying, p_approval_policy character varying, p_approval_id uuid, p_approval_status character varying, p_events_url text, p_resource_binding jsonb DEFAULT '{}'::jsonb) RETURNS assistant.assistant_capability_executions
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row assistant_capability_executions;
BEGIN
    IF jsonb_typeof(p_resource_binding) <> 'object' THEN
        RAISE EXCEPTION 'ASSISTANT_CAPABILITY_RESOURCE_BINDING_INVALID'
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_row
      FROM assistant_capability_executions
     WHERE (run_id, tool_call_id, attempt_id) =
           (p_run_id, p_tool_call_id, p_attempt_id)
        OR (
            tenant_id = p_tenant_id
            AND user_id = p_user_id
            AND session_id = p_session_id
            AND idempotency_key = p_idempotency_key
        )
     ORDER BY created_at
     LIMIT 1
     FOR UPDATE;

    IF FOUND THEN
        IF v_row.lease_id IS DISTINCT FROM p_lease_id
           OR v_row.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_row.user_id IS DISTINCT FROM p_user_id
           OR v_row.session_id IS DISTINCT FROM p_session_id
           OR v_row.run_id IS DISTINCT FROM p_run_id
           OR v_row.tool_call_id IS DISTINCT FROM p_tool_call_id
           OR v_row.attempt_id IS DISTINCT FROM p_attempt_id
           OR v_row.capability_id IS DISTINCT FROM p_capability_id
           OR v_row.capability_revision IS DISTINCT FROM p_capability_revision
           OR v_row.arguments_sha256 IS DISTINCT FROM p_arguments_sha256
           OR v_row.idempotency_key IS DISTINCT FROM p_idempotency_key
           OR v_row.effect IS DISTINCT FROM p_effect
           OR v_row.approval_policy IS DISTINCT FROM p_approval_policy
           OR v_row.approval_id IS DISTINCT FROM p_approval_id
           OR v_row.resource_binding IS DISTINCT FROM p_resource_binding
        THEN
            RAISE EXCEPTION 'ASSISTANT_CAPABILITY_IDEMPOTENCY_CONFLICT'
                USING ERRCODE = '23505';
        END IF;
        RETURN v_row;
    END IF;

    INSERT INTO assistant_capability_executions (
        execution_id, lease_id, tenant_id, user_id, session_id, run_id,
        tool_call_id, attempt_id, capability_id, capability_revision,
        arguments, arguments_sha256, idempotency_key, effect,
        approval_policy, approval_id, approval_status, status, events_url,
        resource_binding
    ) VALUES (
        p_execution_id, p_lease_id, p_tenant_id, p_user_id, p_session_id,
        p_run_id, p_tool_call_id, p_attempt_id, p_capability_id,
        p_capability_revision, p_arguments, p_arguments_sha256,
        p_idempotency_key, p_effect, p_approval_policy, p_approval_id,
        p_approval_status,
        CASE WHEN p_approval_status = 'pending'
            THEN 'awaiting_approval' ELSE 'published' END,
        p_events_url, p_resource_binding
    ) RETURNING * INTO v_row;
    RETURN v_row;
EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_row
      FROM assistant_capability_executions
     WHERE (run_id, tool_call_id, attempt_id) =
           (p_run_id, p_tool_call_id, p_attempt_id)
        OR (
            tenant_id = p_tenant_id
            AND user_id = p_user_id
            AND session_id = p_session_id
            AND idempotency_key = p_idempotency_key
        )
     ORDER BY created_at
     LIMIT 1;
    IF FOUND
       AND v_row.lease_id = p_lease_id
       AND v_row.tenant_id = p_tenant_id
       AND v_row.user_id = p_user_id
       AND v_row.session_id = p_session_id
       AND v_row.run_id = p_run_id
       AND v_row.tool_call_id = p_tool_call_id
       AND v_row.attempt_id = p_attempt_id
       AND v_row.capability_id = p_capability_id
       AND v_row.capability_revision = p_capability_revision
       AND v_row.arguments_sha256 = p_arguments_sha256
       AND v_row.idempotency_key = p_idempotency_key
       AND v_row.effect = p_effect
       AND v_row.approval_policy = p_approval_policy
       AND v_row.approval_id IS NOT DISTINCT FROM p_approval_id
       AND v_row.resource_binding IS NOT DISTINCT FROM p_resource_binding
    THEN
        RETURN v_row;
    END IF;
    RAISE EXCEPTION 'ASSISTANT_CAPABILITY_IDEMPOTENCY_CONFLICT'
        USING ERRCODE = '23505';
END;
$$;

CREATE FUNCTION assistant.reserve_assistant_runtime_model_call(p_call_id uuid, p_lease_id uuid, p_request_sha256 character, p_estimated_input_tokens bigint, p_reserved_output_tokens bigint, p_reserved_cost_microusd bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_lease assistant_runtime_model_leases%ROWTYPE;
BEGIN
    SELECT * INTO v_lease
      FROM assistant_runtime_model_leases
     WHERE lease_id = p_lease_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_LEASE_NOT_FOUND'
            USING ERRCODE = '42501';
    END IF;
    IF v_lease.status <> 'active' OR v_lease.expires_at <= NOW() THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_LEASE_INACTIVE'
            USING ERRCODE = '42501';
    END IF;
    IF EXISTS (
        SELECT 1 FROM assistant_runtime_snapshot_revocations
         WHERE snapshot_id = v_lease.snapshot_id
    ) OR NOT EXISTS (
        SELECT 1 FROM assistant_runs
         WHERE run_id = v_lease.run_id
           AND status = 'running'
           AND engine = 'agent_runtime'
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_LEASE_REVOKED'
            USING ERRCODE = '42501';
    END IF;
    IF v_lease.calls_reserved >= v_lease.max_calls
       OR v_lease.reserved_input_tokens + p_estimated_input_tokens > v_lease.max_input_tokens
       OR v_lease.reserved_output_tokens + p_reserved_output_tokens > v_lease.max_output_tokens
       OR v_lease.reserved_cost_microusd + p_reserved_cost_microusd > v_lease.max_cost_microusd THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_LEASE_BUDGET_EXHAUSTED'
            USING ERRCODE = '53000';
    END IF;
    IF EXISTS (
        SELECT 1 FROM assistant_runtime_model_calls
         WHERE lease_id = p_lease_id AND request_sha256 = p_request_sha256
    ) THEN
        RAISE EXCEPTION 'ASSISTANT_RUNTIME_MODEL_CALL_REPLAYED'
            USING ERRCODE = '55000';
    END IF;

    INSERT INTO assistant_runtime_model_calls (
        call_id, lease_id, snapshot_id, run_id, tenant_id, user_id,
        session_id, request_sha256, estimated_input_tokens,
        reserved_output_tokens, reserved_cost_microusd
    ) VALUES (
        p_call_id, v_lease.lease_id, v_lease.snapshot_id, v_lease.run_id,
        v_lease.tenant_id, v_lease.user_id, v_lease.session_id,
        p_request_sha256, p_estimated_input_tokens, p_reserved_output_tokens,
        p_reserved_cost_microusd
    );

    UPDATE assistant_runtime_model_leases
       SET calls_reserved = calls_reserved + 1,
           reserved_input_tokens = reserved_input_tokens + p_estimated_input_tokens,
           reserved_output_tokens = reserved_output_tokens + p_reserved_output_tokens,
           reserved_cost_microusd = reserved_cost_microusd + p_reserved_cost_microusd,
           updated_at = NOW()
     WHERE lease_id = p_lease_id;
END;
$$;

