CREATE FUNCTION gateway.agent_studio_assert_owner_invariant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_tenant_id VARCHAR(255);
    target_agent_id UUID;
    current_owner_id VARCHAR(255);
    current_deleted_at TIMESTAMPTZ;
BEGIN
    target_tenant_id := COALESCE(NEW.tenant_id, OLD.tenant_id);
    target_agent_id := COALESCE(NEW.agent_id, OLD.agent_id);

    SELECT owner_id, deleted_at INTO current_owner_id, current_deleted_at
    FROM agents
    WHERE tenant_id = target_tenant_id
      AND agent_id = target_agent_id;
    IF NOT FOUND OR current_deleted_at IS NOT NULL THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM agent_members
        WHERE tenant_id = target_tenant_id
          AND agent_id = target_agent_id
          AND principal_type = 'user'
          AND principal_id = current_owner_id
          AND role = 'owner'
    ) THEN
        RAISE EXCEPTION 'AGENT_OWNER_INVARIANT'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION gateway.agent_studio_guard_release_evaluation_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'AGENT_RELEASE_EVIDENCE_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status IN ('passed', 'failed', 'cancelled') THEN
        RAISE EXCEPTION 'AGENT_RELEASE_EVIDENCE_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;

    IF (
        to_jsonb(NEW) - ARRAY[
            'status',
            'validation_snapshot',
            'gate_snapshot',
            'started_at',
            'completed_at'
        ]::TEXT[]
    ) IS DISTINCT FROM (
        to_jsonb(OLD) - ARRAY[
            'status',
            'validation_snapshot',
            'gate_snapshot',
            'started_at',
            'completed_at'
        ]::TEXT[]
    ) THEN
        RAISE EXCEPTION 'AGENT_RELEASE_EVIDENCE_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;

    IF NOT (
        (OLD.status = 'queued' AND NEW.status IN ('running', 'cancelled'))
        OR (OLD.status = 'running' AND NEW.status IN ('passed', 'failed', 'cancelled'))
    ) THEN
        RAISE EXCEPTION 'AGENT_RELEASE_LIFECYCLE_INVALID'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'running' AND NEW.started_at IS NULL THEN
        RAISE EXCEPTION 'AGENT_RELEASE_LIFECYCLE_INVALID'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.status IN ('passed', 'failed', 'cancelled') AND NEW.completed_at IS NULL THEN
        RAISE EXCEPTION 'AGENT_RELEASE_LIFECYCLE_INVALID'
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION gateway.agent_studio_protect_last_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_count INTEGER;
    replacement_owner_id VARCHAR(255);
    agent_deleted_at TIMESTAMPTZ;
BEGIN
    IF OLD.role <> 'owner' THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.role = 'owner' THEN
        RETURN NEW;
    END IF;

    SELECT deleted_at INTO agent_deleted_at
    FROM agents
    WHERE tenant_id = OLD.tenant_id AND agent_id = OLD.agent_id
    FOR UPDATE;
    IF NOT FOUND OR agent_deleted_at IS NOT NULL THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;

    SELECT COUNT(*) INTO owner_count
    FROM agent_members
    WHERE tenant_id = OLD.tenant_id
      AND agent_id = OLD.agent_id
      AND role = 'owner';

    IF owner_count <= 1 THEN
        RAISE EXCEPTION 'AGENT_LAST_OWNER'
            USING ERRCODE = '23514';
    END IF;
    SELECT principal_id INTO replacement_owner_id
    FROM agent_members
    WHERE tenant_id = OLD.tenant_id
      AND agent_id = OLD.agent_id
      AND role = 'owner'
      AND NOT (
          principal_type = OLD.principal_type
          AND principal_id = OLD.principal_id
      )
    ORDER BY created_at, principal_id
    LIMIT 1;
    UPDATE agents
    SET owner_id = replacement_owner_id
    WHERE tenant_id = OLD.tenant_id
      AND agent_id = OLD.agent_id
      AND owner_id = OLD.principal_id;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION gateway.agent_studio_protect_member_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.agent_id IS DISTINCT FROM OLD.agent_id
       OR NEW.principal_type IS DISTINCT FROM OLD.principal_type
       OR NEW.principal_id IS DISTINCT FROM OLD.principal_id THEN
        RAISE EXCEPTION 'AGENT_MEMBER_IDENTITY_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION gateway.agent_studio_protect_version_binding_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_sealed BOOLEAN;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'AGENT_VERSION_IMMUTABLE'
            USING ERRCODE = '55000';
    END IF;

    SELECT bindings_sealed INTO parent_sealed
    FROM agent_versions
    WHERE tenant_id = NEW.tenant_id
      AND agent_version_id = NEW.agent_version_id;

    -- A missing tenant-qualified parent must flow to the composite FK so the
    -- caller receives a foreign-key failure rather than an immutability error.
    IF parent_sealed IS NULL OR parent_sealed = FALSE THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'AGENT_VERSION_IMMUTABLE'
        USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION gateway.agent_studio_protect_version_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND OLD.bindings_sealed = FALSE
       AND NEW.bindings_sealed = TRUE
       AND (TO_JSONB(NEW) - 'bindings_sealed')
           IS NOT DISTINCT FROM (TO_JSONB(OLD) - 'bindings_sealed') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'AGENT_VERSION_IMMUTABLE'
        USING ERRCODE = '55000';
END;
$$;

