CREATE FUNCTION gateway.claim_local_node_dispatch(p_execution_id uuid, p_tenant_id character varying, p_user_id character varying, p_session_id character varying, p_fence uuid, p_effect character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE v_row local_node_executions;
DECLARE v_grant_revision BIGINT;
DECLARE v_grant_status VARCHAR;
BEGIN
    SELECT * INTO v_row FROM local_node_executions
     WHERE execution_id=p_execution_id AND tenant_id=p_tenant_id AND user_id=p_user_id
       AND session_id=p_session_id FOR UPDATE;
    IF NOT FOUND OR v_row.dispatch_fence IS NOT NULL OR
       v_row.status IN ('succeeded','failed','cancelled','timeout','side_effect_unknown') THEN
        RETURN FALSE;
    END IF;
    IF p_effect IN ('write','unknown') AND v_row.approval_status <> 'approved' THEN
        RETURN FALSE;
    END IF;
    IF v_row.grant_id IS NOT NULL THEN
        SELECT revision,status INTO v_grant_revision,v_grant_status
          FROM local_node_grants WHERE grant_id=v_row.grant_id
            AND tenant_id=v_row.tenant_id AND user_id=v_row.user_id
            AND device_id=v_row.device_id;
        IF NOT FOUND OR v_grant_status <> 'active'
           OR v_grant_revision IS DISTINCT FROM v_row.grant_revision THEN
            RETURN FALSE;
        END IF;
    END IF;
    UPDATE local_node_executions SET dispatch_fence=p_fence,dispatched_at=now(),
      status='dispatched',approval_status=CASE WHEN p_effect IN ('write','unknown') THEN 'consumed' ELSE approval_status END,
      updated_at=now() WHERE execution_id=p_execution_id;
    RETURN TRUE;
END;
$$;

CREATE FUNCTION gateway.cleanup_old_usage_records(retention_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM usage_records
    WHERE created_at < CURRENT_TIMESTAMP - (retention_days || ' days')::INTERVAL;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

CREATE FUNCTION gateway.record_artifact_share_quiz_attempt(p_share_code character varying, p_token_hash character, p_display_name character varying, p_attempt_id uuid, p_quiz_id uuid, p_answers jsonb, p_total_score double precision, p_correct_count integer, p_total_count integer, p_client_ip character varying) RETURNS TABLE(attempt_id uuid, started_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'assistant'
    AS $$
DECLARE
    share_row assistant.artifact_shares%ROWTYPE;
    token_row assistant.artifact_share_attempt_tokens%ROWTYPE;
    claimed_rows INT := 0;
    attempt_started_at TIMESTAMPTZ := clock_timestamp();
BEGIN
    SELECT *
    INTO share_row
    FROM assistant.artifact_shares
    WHERE share_code = p_share_code
    FOR UPDATE;

    IF NOT FOUND
       OR NOT share_row.is_active
       OR (share_row.expires_at IS NOT NULL
           AND share_row.expires_at <= clock_timestamp()) THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P4040',
            MESSAGE = 'Share not found or expired';
    END IF;
    IF share_row.kind <> 'quiz' OR p_quiz_id IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P4000',
            MESSAGE = 'Share is not a valid quiz';
    END IF;
    IF share_row.max_attempts IS NOT NULL
       AND share_row.attempt_count >= share_row.max_attempts THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P4290',
            MESSAGE = 'Maximum attempts reached';
    END IF;
    IF share_row.require_name AND p_display_name IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P4000',
            MESSAGE = 'This share requires a name before submitting';
    END IF;

    IF share_row.time_limit_minutes IS NOT NULL AND p_token_hash IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P4000',
            MESSAGE = 'An attempt token is required for timed shares';
    END IF;

    IF p_token_hash IS NOT NULL THEN
        SELECT *
        INTO token_row
        FROM assistant.artifact_share_attempt_tokens
        WHERE token_hash = p_token_hash
        FOR UPDATE;

        IF NOT FOUND OR token_row.share_id <> share_row.id THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P4000',
                MESSAGE = 'Attempt token is invalid or expired';
        END IF;
        IF token_row.consumed_at IS NOT NULL THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P4090',
                MESSAGE = 'Attempt token has already been consumed';
        END IF;
        IF token_row.expires_at <= clock_timestamp() THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P4000',
                MESSAGE = 'Attempt token is invalid or expired';
        END IF;
        attempt_started_at := token_row.started_at;
    END IF;

    IF p_display_name IS NOT NULL THEN
        INSERT INTO assistant.artifact_share_submitters (share_id, display_name)
        VALUES (share_row.id, p_display_name)
        ON CONFLICT (share_id, display_name) DO NOTHING;
        GET DIAGNOSTICS claimed_rows = ROW_COUNT;
        IF claimed_rows <> 1 THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P4090',
                MESSAGE = 'This display name has already submitted';
        END IF;
    END IF;

    UPDATE assistant.artifact_shares
    SET attempt_count = attempt_count + 1
    WHERE id = share_row.id;

    IF p_token_hash IS NOT NULL THEN
        UPDATE assistant.artifact_share_attempt_tokens
        SET consumed_at = clock_timestamp()
        WHERE id = token_row.id;
    END IF;

    INSERT INTO assistant.quiz_attempts (
        id, quiz_id, user_id, share_id, display_name, answers,
        total_score, correct_count, total_count, started_at, completed_at,
        status, client_ip, exam_id
    )
    VALUES (
        p_attempt_id, p_quiz_id, NULL, share_row.id, p_display_name, p_answers,
        p_total_score, p_correct_count, p_total_count, attempt_started_at,
        clock_timestamp(), 'completed', p_client_ip, NULL
    );

    RETURN QUERY SELECT p_attempt_id, attempt_started_at;
END
$$;

