CREATE FUNCTION knowledge.prune_kb_document_progress_events() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'knowledge', 'pg_catalog'
    AS $$
DECLARE
    retained_floor BIGINT;
BEGIN
    -- Seven days is longer than the browser reconnect contract. Run the indexed
    -- age prune on each new transition so an inactive dataset needs no scheduler.
    DELETE FROM knowledge.kb_document_progress_events
    WHERE dataset_id = NEW.dataset_id
      AND created_at < NOW() - INTERVAL '7 days';

    -- The age window can still be noisy during bulk ingestion. Amortize the
    -- per-dataset row cap to one indexed check per 128 global events.
    IF MOD(NEW.event_sequence, 128) = 0 THEN
        SELECT MIN(recent.event_sequence)
        INTO retained_floor
        FROM (
            SELECT event_sequence
            FROM knowledge.kb_document_progress_events
            WHERE dataset_id = NEW.dataset_id
            ORDER BY event_sequence DESC
            LIMIT 10000
        ) AS recent;

        IF retained_floor IS NOT NULL THEN
            DELETE FROM knowledge.kb_document_progress_events
            WHERE dataset_id = NEW.dataset_id
              AND event_sequence < retained_floor;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION knowledge.record_kb_document_progress_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'knowledge', 'pg_catalog'
    AS $$
DECLARE
    display_state TEXT;
    current_stage TEXT;
    terminal_state BOOLEAN;
    event_payload JSONB;
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO kb_document_progress_events (
            dataset_id, document_id, event_type, payload
        )
        VALUES (
            OLD.dataset_id,
            OLD.document_id,
            'deleted',
            jsonb_build_object(
                'document_id', OLD.document_id,
                'progress', jsonb_build_object(
                    'percent', 100,
                    'stage', 'deleted',
                    'state', 'deleted'
                ),
                'terminal', TRUE
            )
        );
        RETURN OLD;
    END IF;

    -- UPDATE triggers also fire for content/metadata writes that do not alter
    -- the progress contract.  Avoid creating replay noise for those writes.
    IF TG_OP = 'UPDATE'
       AND ROW(
            NEW.status,
            NEW.progress,
            NEW.error,
            NEW.metadata,
            NEW.enabled,
            NEW.disabled_at,
            NEW.disabled_by,
            NEW.archived,
            NEW.archived_reason,
            NEW.archived_by,
            NEW.archived_at,
            NEW.started_at,
            NEW.completed_at,
            NEW.parsing_started_at,
            NEW.splitting_started_at,
            NEW.indexing_started_at
       ) IS NOT DISTINCT FROM ROW(
            OLD.status,
            OLD.progress,
            OLD.error,
            OLD.metadata,
            OLD.enabled,
            OLD.disabled_at,
            OLD.disabled_by,
            OLD.archived,
            OLD.archived_reason,
            OLD.archived_by,
            OLD.archived_at,
            OLD.started_at,
            OLD.completed_at,
            OLD.parsing_started_at,
            OLD.splitting_started_at,
            OLD.indexing_started_at
       ) THEN
        RETURN NEW;
    END IF;

    display_state := CASE
        WHEN COALESCE(NEW.archived, FALSE) THEN 'archived'
        WHEN NEW.status IN ('error', 'failed') THEN 'error'
        WHEN NEW.status = 'paused' THEN 'paused'
        WHEN NEW.status = 'completed' AND COALESCE(NEW.enabled, TRUE) = FALSE
            THEN 'disabled'
        WHEN NEW.status = 'completed' THEN 'available'
        WHEN NEW.status IN ('waiting', 'queued', 'pending', 'uploaded', 'detecting')
            THEN 'queuing'
        ELSE 'indexing'
    END;
    current_stage := CASE
        WHEN NEW.status IN ('waiting', 'queued', 'pending', 'uploaded', 'detecting')
            THEN 'waiting'
        WHEN NEW.status IN ('parsing', 'splitting', 'indexing') THEN NEW.status
        WHEN NEW.status IN ('completed', 'error', 'failed') THEN NEW.status
        ELSE 'indexing'
    END;
    terminal_state := NEW.status IN ('completed', 'error', 'failed');
    event_payload := jsonb_build_object(
        'document_id', NEW.document_id,
        'progress', jsonb_build_object(
            'percent', GREATEST(0::NUMERIC, LEAST(100::NUMERIC, COALESCE(NEW.progress, 0))),
            'stage', current_stage,
            'state', display_state
        ),
        'terminal', terminal_state,
        'error', CASE WHEN NEW.status IN ('error', 'failed')
            THEN LEFT(COALESCE(NEW.error, ''), 2000) ELSE NULL END
    );

    INSERT INTO kb_document_progress_events (
        dataset_id, document_id, event_type, payload
    )
    VALUES (
        NEW.dataset_id,
        NEW.document_id,
        CASE WHEN terminal_state THEN 'terminal' ELSE 'progress' END,
        event_payload
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION knowledge.segments_text_search_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.text_search := to_tsvector('simple', COALESCE(NEW.text, ''));
    RETURN NEW;
END;
$$;

