    session_id character varying(100) NOT NULL,
    phase character varying(64) NOT NULL,
    iteration integer DEFAULT 0 NOT NULL,
    message_state_hash character varying(64) NOT NULL,
    pending_tool jsonb DEFAULT '{}'::jsonb NOT NULL,
    approval_id uuid,
    idempotency_keys jsonb DEFAULT '{}'::jsonb NOT NULL,
    resume_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(32) DEFAULT 'running'::character varying NOT NULL,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_id uuid,
    agent_version_id uuid,
    agent_draft_revision integer,
    publication_id uuid,
    channel character varying(16),
    runtime_fingerprint text,
    agent_spec_hash text,
    CONSTRAINT assistant_run_checkpoints_agent_runtime_channel_check CHECK (((channel IS NULL) OR ((channel)::text = ANY (ARRAY[('preview'::character varying)::text, ('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text, ('builtin'::character varying)::text])))),
    CONSTRAINT assistant_run_checkpoints_agent_runtime_shape_check CHECK ((((agent_id IS NULL) AND (agent_version_id IS NULL) AND (agent_draft_revision IS NULL) AND (publication_id IS NULL) AND (channel IS NULL) AND (runtime_fingerprint IS NULL) AND (agent_spec_hash IS NULL)) OR ((agent_id IS NOT NULL) AND (runtime_fingerprint IS NOT NULL) AND (agent_spec_hash IS NOT NULL) AND ((((channel)::text = 'preview'::text) AND (agent_draft_revision >= 1) AND (agent_version_id IS NULL) AND (publication_id IS NULL)) OR (((channel)::text = ANY (ARRAY[('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text])) AND (agent_draft_revision IS NULL) AND (agent_version_id IS NOT NULL) AND (publication_id IS NOT NULL))))))
);

CREATE TABLE assistant.assistant_runs (
    run_id uuid NOT NULL,
    tenant_id character varying(64) NOT NULL,
    user_id character varying(64) NOT NULL,
    session_id character varying(100) NOT NULL,
    status character varying(32) DEFAULT 'running'::character varying NOT NULL,
    engine character varying(32) DEFAULT 'agent_loop'::character varying NOT NULL,
    execution_profile character varying(16) DEFAULT 'safe'::character varying NOT NULL,
    memory_mode character varying(16) DEFAULT 'auto'::character varying NOT NULL,
    os_agent_enabled boolean DEFAULT false NOT NULL,
    request_preview text DEFAULT ''::text NOT NULL,
    usage jsonb DEFAULT '{}'::jsonb NOT NULL,
    error text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_id uuid,
    agent_version_id uuid,
    agent_draft_revision integer,
    publication_id uuid,
    channel character varying(16),
    runtime_fingerprint text,
    agent_spec_hash text,
    harness_thread_id uuid,
    harness_turn_id character varying(255),
    runtime_snapshot_id uuid,
    kernel_revision character varying(100),
    capability_revision bigint,
    CONSTRAINT assistant_runs_agent_runtime_channel_check CHECK (((channel IS NULL) OR ((channel)::text = ANY (ARRAY[('preview'::character varying)::text, ('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text, ('builtin'::character varying)::text])))),
    CONSTRAINT assistant_runs_agent_runtime_shape_check CHECK ((((agent_id IS NULL) AND (agent_version_id IS NULL) AND (agent_draft_revision IS NULL) AND (publication_id IS NULL) AND (channel IS NULL) AND (runtime_fingerprint IS NULL) AND (agent_spec_hash IS NULL)) OR ((agent_id IS NOT NULL) AND (runtime_fingerprint IS NOT NULL) AND (agent_spec_hash IS NOT NULL) AND ((((channel)::text = 'preview'::text) AND (agent_draft_revision >= 1) AND (agent_version_id IS NULL) AND (publication_id IS NULL)) OR (((channel)::text = ANY (ARRAY[('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text])) AND (agent_draft_revision IS NULL) AND (agent_version_id IS NOT NULL) AND (publication_id IS NOT NULL)))))),
    CONSTRAINT assistant_runs_harness_shape_check CHECK (((((engine)::text <> 'agent_runtime'::text) AND (harness_thread_id IS NULL) AND (harness_turn_id IS NULL) AND (runtime_snapshot_id IS NULL) AND (kernel_revision IS NULL) AND (capability_revision IS NULL)) OR (((engine)::text = 'agent_runtime'::text) AND (harness_thread_id IS NOT NULL) AND (harness_turn_id IS NOT NULL) AND (runtime_snapshot_id IS NOT NULL) AND (kernel_revision IS NOT NULL) AND (capability_revision >= 1))))
);

