CREATE TABLE assistant.assistant_runtime_model_calls (
    call_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    run_id uuid NOT NULL,
    tenant_id character varying(255) NOT NULL,
    user_id character varying(255) NOT NULL,
    session_id character varying(255) NOT NULL,
    request_sha256 character(64) NOT NULL,
    status character varying(32) DEFAULT 'reserved'::character varying NOT NULL,
    estimated_input_tokens bigint NOT NULL,
    reserved_output_tokens bigint NOT NULL,
    reserved_cost_microusd bigint NOT NULL,
    input_tokens bigint,
    output_tokens bigint,
    cost_microusd bigint,
    provider_request_id character varying(255),
    error_code character varying(100),
    reserved_at timestamp with time zone DEFAULT now() NOT NULL,
    dispatched_at timestamp with time zone,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT assistant_runtime_model_calls_cost_microusd_check CHECK (((cost_microusd IS NULL) OR (cost_microusd >= 0))),
