    CONSTRAINT assistant_runtime_model_leases_capability_revision_check CHECK ((capability_revision >= 1)),
    CONSTRAINT assistant_runtime_model_leases_counter_check CHECK (((calls_completed <= calls_reserved) AND (calls_reserved <= max_calls))),
    CONSTRAINT assistant_runtime_model_leases_max_calls_check CHECK (((max_calls >= 1) AND (max_calls <= 128))),
    CONSTRAINT assistant_runtime_model_leases_max_cost_microusd_check CHECK ((max_cost_microusd > 0)),
    CONSTRAINT assistant_runtime_model_leases_max_input_tokens_check CHECK ((max_input_tokens > 0)),
    CONSTRAINT assistant_runtime_model_leases_max_output_tokens_check CHECK ((max_output_tokens > 0)),
    CONSTRAINT assistant_runtime_model_leases_nonce_check CHECK ((nonce_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT assistant_runtime_model_leases_reserved_cost_microusd_check CHECK ((reserved_cost_microusd >= 0)),
    CONSTRAINT assistant_runtime_model_leases_reserved_input_tokens_check CHECK ((reserved_input_tokens >= 0)),
    CONSTRAINT assistant_runtime_model_leases_reserved_output_tokens_check CHECK ((reserved_output_tokens >= 0)),
    CONSTRAINT assistant_runtime_model_leases_status_check CHECK (((status)::text = ANY (ARRAY[('active'::character varying)::text, ('exhausted'::character varying)::text, ('revoked'::character varying)::text, ('expired'::character varying)::text]))),
    CONSTRAINT assistant_runtime_model_leases_time_check CHECK ((expires_at > issued_at)),
    CONSTRAINT assistant_runtime_model_leases_used_cost_microusd_check CHECK ((used_cost_microusd >= 0)),
    CONSTRAINT assistant_runtime_model_leases_used_input_tokens_check CHECK ((used_input_tokens >= 0)),
    CONSTRAINT assistant_runtime_model_leases_used_output_tokens_check CHECK ((used_output_tokens >= 0))
);

