CREATE TABLE gateway.agent_data_deletion_requests (
    deletion_id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id character varying(255) NOT NULL,
    agent_id uuid NOT NULL,
    scope character varying(16) NOT NULL,
    subject_user_id character varying(255),
    idempotency_key character varying(255) NOT NULL,
    status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    object_keys jsonb DEFAULT '[]'::jsonb NOT NULL,
    deleted_counts jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code character varying(128),
    requested_by character varying(255) NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_attempt_at timestamp with time zone,
    CONSTRAINT agent_data_deletion_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT agent_data_deletion_requests_scope_check CHECK (((scope)::text = ANY (ARRAY[('retention'::character varying)::text, ('user'::character varying)::text, ('tenant'::character varying)::text]))),
    CONSTRAINT agent_data_deletion_requests_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('completed'::character varying)::text, ('failed'::character varying)::text, ('blocked'::character varying)::text]))),
    CONSTRAINT agent_data_deletion_subject_check CHECK (((((scope)::text = 'user'::text) AND (subject_user_id IS NOT NULL)) OR (((scope)::text <> 'user'::text) AND (subject_user_id IS NULL))))
);

CREATE TABLE gateway.agent_draft_knowledge_bindings (
    tenant_id character varying(255) NOT NULL,
    draft_id uuid NOT NULL,
    dataset_id character varying(255) NOT NULL,
    retrieval_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    bound_by character varying(255),
    authorization_checked_at timestamp with time zone
);

CREATE TABLE gateway.agent_draft_skill_bindings (
    tenant_id character varying(255) NOT NULL,
    draft_id uuid NOT NULL,
    skill_id uuid NOT NULL,
    skill_version_id uuid NOT NULL,
    skill_name character varying(128) NOT NULL,
    bound_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE gateway.agent_drafts (
    tenant_id character varying(255) NOT NULL,
    draft_id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    schema_version character varying(64) DEFAULT 'agent-spec/v1'::character varying NOT NULL,
    spec jsonb DEFAULT '{}'::jsonb NOT NULL,
    spec_hash character(64) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_drafts_revision_check CHECK ((revision >= 1)),
    CONSTRAINT agent_drafts_spec_hash_check CHECK ((spec_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE gateway.agent_governance_policies (
    tenant_id character varying(255) NOT NULL,
    agent_id uuid NOT NULL,
    trace_retention_days integer DEFAULT 90 NOT NULL,
    runtime_retention_days integer DEFAULT 30 NOT NULL,
    attachment_retention_days integer DEFAULT 1 NOT NULL,
    legal_hold boolean DEFAULT false NOT NULL,
    principal_requests_per_minute integer DEFAULT 30 NOT NULL,
    principal_requests_per_day integer DEFAULT 1000 NOT NULL,
    ip_requests_per_minute integer DEFAULT 60 NOT NULL,
    ip_requests_per_day integer DEFAULT 2000 NOT NULL,
    publication_requests_per_minute integer DEFAULT 300 NOT NULL,
    publication_requests_per_day integer DEFAULT 10000 NOT NULL,
    alert_threshold_percent integer DEFAULT 90 NOT NULL,
    cache_epoch bigint DEFAULT 0 NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    max_agents_per_tenant integer DEFAULT 100 NOT NULL,
    max_active_publications integer DEFAULT 10 NOT NULL,
    max_concurrent_runs integer DEFAULT 25 NOT NULL,
    max_daily_tokens bigint DEFAULT 10000000 NOT NULL,
    max_daily_mcp_calls bigint DEFAULT 100000 NOT NULL,
    max_storage_bytes bigint DEFAULT '10737418240'::bigint NOT NULL,
    CONSTRAINT agent_governance_max_active_publications_check CHECK ((max_active_publications > 0)),
    CONSTRAINT agent_governance_max_agents_per_tenant_check CHECK ((max_agents_per_tenant > 0)),
    CONSTRAINT agent_governance_max_concurrent_runs_check CHECK ((max_concurrent_runs > 0)),
    CONSTRAINT agent_governance_max_daily_mcp_calls_check CHECK ((max_daily_mcp_calls > 0)),
    CONSTRAINT agent_governance_max_daily_tokens_check CHECK ((max_daily_tokens > 0)),
    CONSTRAINT agent_governance_max_storage_bytes_check CHECK ((max_storage_bytes > 0)),
    CONSTRAINT agent_governance_policies_alert_threshold_percent_check CHECK (((alert_threshold_percent >= 1) AND (alert_threshold_percent <= 100))),
    CONSTRAINT agent_governance_policies_attachment_retention_days_check CHECK (((attachment_retention_days >= 1) AND (attachment_retention_days <= 3650))),
    CONSTRAINT agent_governance_policies_cache_epoch_check CHECK ((cache_epoch >= 0)),
    CONSTRAINT agent_governance_policies_ip_requests_per_day_check CHECK ((ip_requests_per_day > 0)),
    CONSTRAINT agent_governance_policies_ip_requests_per_minute_check CHECK ((ip_requests_per_minute > 0)),
    CONSTRAINT agent_governance_policies_principal_requests_per_day_check CHECK ((principal_requests_per_day > 0)),
    CONSTRAINT agent_governance_policies_principal_requests_per_minute_check CHECK ((principal_requests_per_minute > 0)),
    CONSTRAINT agent_governance_policies_publication_requests_per_day_check CHECK ((publication_requests_per_day > 0)),
    CONSTRAINT agent_governance_policies_publication_requests_per_minute_check CHECK ((publication_requests_per_minute > 0)),
    CONSTRAINT agent_governance_policies_runtime_retention_days_check CHECK (((runtime_retention_days >= 1) AND (runtime_retention_days <= 3650))),
    CONSTRAINT agent_governance_policies_trace_retention_days_check CHECK (((trace_retention_days >= 1) AND (trace_retention_days <= 3650)))
);

CREATE TABLE gateway.agent_members (
    tenant_id character varying(255) NOT NULL,
    agent_id uuid NOT NULL,
    principal_type character varying(32) DEFAULT 'user'::character varying NOT NULL,
    principal_id character varying(255) NOT NULL,
    user_principal_id character varying(255) GENERATED ALWAYS AS (
CASE
    WHEN ((principal_type)::text = 'user'::text) THEN principal_id
    ELSE NULL::character varying
END) STORED,
    role character varying(16) NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_members_group_fail_closed CHECK (((principal_type)::text = 'user'::text)),
    CONSTRAINT agent_members_principal_type_check CHECK (((principal_type)::text = ANY (ARRAY[('user'::character varying)::text, ('group'::character varying)::text]))),
    CONSTRAINT agent_members_role_check CHECK (((role)::text = ANY (ARRAY[('owner'::character varying)::text, ('editor'::character varying)::text, ('viewer'::character varying)::text])))
);

CREATE TABLE gateway.agent_publications (
    tenant_id character varying(255) NOT NULL,
    publication_id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    channel character varying(16) NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    version_id uuid,
    auth_mode character varying(16) DEFAULT 'private'::character varying NOT NULL,
    policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(16) DEFAULT 'draft'::character varying NOT NULL,
    created_by character varying(255) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_publications_auth_mode_check CHECK (((auth_mode)::text = ANY (ARRAY[('private'::character varying)::text, ('tenant'::character varying)::text, ('public'::character varying)::text, ('token'::character varying)::text]))),
    CONSTRAINT agent_publications_channel_check CHECK (((channel)::text = ANY (ARRAY[('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text]))),
    CONSTRAINT agent_publications_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('active'::character varying)::text, ('disabled'::character varying)::text, ('degraded'::character varying)::text])))
);

CREATE TABLE gateway.agent_publish_events (
    tenant_id character varying(255) NOT NULL,
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    publication_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    from_version_id uuid,
    to_version_id uuid NOT NULL,
    actor_id character varying(255) NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    validation_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    operation character varying(16) DEFAULT 'promote'::character varying NOT NULL,
    release_evaluation_id uuid,
    request_hash character(64),
    CONSTRAINT agent_publish_events_operation_check CHECK (((operation)::text = ANY (ARRAY[('promote'::character varying)::text, ('rollback'::character varying)::text]))),
    CONSTRAINT agent_publish_events_request_hash_check CHECK (((request_hash IS NULL) OR (request_hash ~ '^[0-9a-f]{64}$'::text)))
);

CREATE TABLE gateway.agent_release_evaluation_events (
    tenant_id character varying(255) NOT NULL,
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    evaluation_id uuid NOT NULL,
    sequence integer NOT NULL,
    status character varying(16) NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_release_evaluation_events_sequence_check CHECK ((sequence >= 1)),
    CONSTRAINT agent_release_evaluation_events_status_check CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('passed'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('stale'::character varying)::text])))
);

CREATE TABLE gateway.agent_release_evaluations (
    tenant_id character varying(255) NOT NULL,
    evaluation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    draft_id uuid NOT NULL,
    draft_revision integer NOT NULL,
    spec_hash character(64) NOT NULL,
    runtime_fingerprint jsonb NOT NULL,
    runtime_fingerprint_hash character(64) NOT NULL,
    release_identity_hash character(64) NOT NULL,
    profile_id character varying(64) NOT NULL,
    profile_version character varying(64) NOT NULL,
    dataset_id uuid,
    experiment_run_id uuid,
    channel character varying(16) NOT NULL,
    auth_mode character varying(16) DEFAULT 'private'::character varying NOT NULL,
    channel_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    channel_policy_hash character(64) NOT NULL,
    status character varying(16) NOT NULL,
    validation_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    gate_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    dataset_version character varying(64),
    dataset_manifest_hash character(64),
    evaluation_identity_hash character(64),
    started_at timestamp with time zone,
    CONSTRAINT agent_release_evaluations_auth_mode_check CHECK (((auth_mode)::text = ANY (ARRAY[('private'::character varying)::text, ('tenant'::character varying)::text, ('public'::character varying)::text, ('token'::character varying)::text]))),
    CONSTRAINT agent_release_evaluations_channel_check CHECK (((channel)::text = ANY (ARRAY[('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text]))),
    CONSTRAINT agent_release_evaluations_channel_policy_hash_check CHECK ((channel_policy_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_release_evaluations_dataset_manifest_hash_check CHECK (((dataset_manifest_hash IS NULL) OR (dataset_manifest_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT agent_release_evaluations_draft_revision_check CHECK ((draft_revision >= 1)),
    CONSTRAINT agent_release_evaluations_identity_hash_check CHECK (((evaluation_identity_hash IS NULL) OR (evaluation_identity_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT agent_release_evaluations_release_identity_hash_check CHECK ((release_identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_release_evaluations_runtime_fingerprint_hash_check CHECK ((runtime_fingerprint_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_release_evaluations_spec_hash_check CHECK ((spec_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_release_evaluations_status_check CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('passed'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text])))
);

CREATE TABLE gateway.agent_release_requests (
    tenant_id character varying(255) NOT NULL,
    operation character varying(16) NOT NULL,
    idempotency_key_hash character(64) NOT NULL,
    request_hash character(64) NOT NULL,
    agent_id uuid NOT NULL,
    evaluation_id uuid,
    result_version_id uuid NOT NULL,
    result_publication_id uuid NOT NULL,
    result_event_id uuid NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_release_requests_idempotency_key_hash_check CHECK ((idempotency_key_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_release_requests_operation_check CHECK (((operation)::text = ANY (ARRAY[('promote'::character varying)::text, ('rollback'::character varying)::text]))),
    CONSTRAINT agent_release_requests_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE gateway.agent_trace_events (
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    trace_id uuid NOT NULL,
    span_id uuid,
    event_type character varying(96) NOT NULL,
    sequence_no integer NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_size_bytes integer DEFAULT 0 NOT NULL,
    redacted boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE gateway.agent_trace_outbox (
    job_id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id character varying(64) NOT NULL,
    job_type character varying(96) NOT NULL,
    status character varying(32) DEFAULT 'queued'::character varying NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_agent_trace_outbox_status CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text])))
);

CREATE TABLE gateway.agent_trace_scores (
    score_id uuid DEFAULT gen_random_uuid() NOT NULL,
    trace_id uuid NOT NULL,
    span_id uuid,
    score_name character varying(96) NOT NULL,
    score_type character varying(32) DEFAULT 'numeric'::character varying NOT NULL,
    numeric_value double precision,
    boolean_value boolean,
    categorical_value character varying(96),
    text_value text,
    label character varying(96),
    explanation text,
    scorer_type character varying(32) DEFAULT 'human'::character varying NOT NULL,
    evaluator_version character varying(64),
    created_by character varying(64) NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    target_type character varying(32) DEFAULT 'trace'::character varying NOT NULL,
    target_id character varying(128),
    evaluator_id uuid,
    evaluator_name character varying(128),
    score_source character varying(32) DEFAULT 'human'::character varying NOT NULL,
    confidence double precision,
    CONSTRAINT chk_agent_trace_scores_scorer CHECK (((scorer_type)::text = ANY (ARRAY[('human'::character varying)::text, ('llm'::character varying)::text, ('rule'::character varying)::text, ('system'::character varying)::text]))),
    CONSTRAINT chk_agent_trace_scores_source CHECK (((score_source)::text = ANY (ARRAY[('human'::character varying)::text, ('llm'::character varying)::text, ('rule'::character varying)::text, ('system'::character varying)::text, ('imported'::character varying)::text, ('kb_ragas'::character varying)::text]))),
    CONSTRAINT chk_agent_trace_scores_target_type CHECK (((target_type)::text = ANY (ARRAY[('trace'::character varying)::text, ('span'::character varying)::text, ('thread'::character varying)::text, ('dataset_run'::character varying)::text, ('example'::character varying)::text]))),
    CONSTRAINT chk_agent_trace_scores_type CHECK (((score_type)::text = ANY (ARRAY[('numeric'::character varying)::text, ('categorical'::character varying)::text, ('boolean'::character varying)::text, ('text'::character varying)::text])))
);

CREATE TABLE gateway.agent_trace_spans (
    span_id uuid DEFAULT gen_random_uuid() NOT NULL,
    trace_id uuid NOT NULL,
    parent_span_id uuid,
    span_kind character varying(64) NOT NULL,
    name character varying(160) NOT NULL,
    status character varying(32) DEFAULT 'running'::character varying NOT NULL,
    sequence_no integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    duration_ms integer DEFAULT 0 NOT NULL,
    input_preview text DEFAULT ''::text NOT NULL,
    output_preview text DEFAULT ''::text NOT NULL,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_type character varying(64),
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_agent_trace_spans_status CHECK (((status)::text = ANY (ARRAY[('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('skipped'::character varying)::text])))
);

CREATE TABLE gateway.agent_traces (
    trace_id uuid DEFAULT gen_random_uuid() NOT NULL,
    trace_family character varying(32) DEFAULT 'assistant'::character varying NOT NULL,
    workflow_kind character varying(64) DEFAULT 'ai_assistant_chat'::character varying NOT NULL,
    tenant_id character varying(64) NOT NULL,
    user_id character varying(64) NOT NULL,
    session_id character varying(100),
    run_id character varying(100),
    request_id character varying(100),
    otel_trace_id character varying(128),
    traceparent character varying(255),
    model_id character varying(128),
    provider character varying(64),
    status character varying(32) DEFAULT 'running'::character varying NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    first_token_latency_ms integer DEFAULT 0 NOT NULL,
    total_latency_ms integer DEFAULT 0 NOT NULL,
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    total_tokens integer DEFAULT 0 NOT NULL,
    total_cost_cents integer DEFAULT 0 NOT NULL,
    input_preview text DEFAULT ''::text NOT NULL,
    output_preview text DEFAULT ''::text NOT NULL,
    redaction_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    retention_expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_adapter character varying(64),
    thread_id character varying(100),
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    privacy jsonb DEFAULT '{}'::jsonb NOT NULL,
    agent_id uuid,
    agent_version_id uuid,
    agent_draft_revision integer,
    publication_id uuid,
    channel character varying(16),
    runtime_fingerprint text,
    agent_spec_hash text,
    CONSTRAINT agent_traces_agent_runtime_channel_check CHECK (((channel IS NULL) OR ((channel)::text = ANY (ARRAY[('preview'::character varying)::text, ('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text, ('builtin'::character varying)::text])))),
    CONSTRAINT agent_traces_agent_runtime_shape_check CHECK ((((agent_id IS NULL) AND (agent_version_id IS NULL) AND (agent_draft_revision IS NULL) AND (publication_id IS NULL) AND (channel IS NULL) AND (runtime_fingerprint IS NULL) AND (agent_spec_hash IS NULL)) OR ((agent_id IS NOT NULL) AND (runtime_fingerprint IS NOT NULL) AND (agent_spec_hash IS NOT NULL) AND ((((channel)::text = 'preview'::text) AND (agent_draft_revision >= 1) AND (agent_version_id IS NULL) AND (publication_id IS NULL)) OR (((channel)::text = ANY (ARRAY[('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text])) AND (agent_draft_revision IS NULL) AND (agent_version_id IS NOT NULL) AND (publication_id IS NOT NULL)))))),
    CONSTRAINT chk_agent_traces_status CHECK (((status)::text = ANY (ARRAY[('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('timeout'::character varying)::text]))),
    CONSTRAINT chk_agent_traces_trace_family CHECK (((trace_family)::text = ANY (ARRAY[('assistant'::character varying)::text, ('langgraph_proxy'::character varying)::text, ('rag'::character varying)::text])))
);

CREATE TABLE gateway.agent_version_capabilities (
    tenant_id character varying(255) NOT NULL,
    capability_id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_version_id uuid NOT NULL,
    capability_type character varying(32) NOT NULL,
    resource_id character varying(255) DEFAULT ''::character varying NOT NULL,
    resource_version character varying(255),
    schema_hash character(64),
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_version_capabilities_capability_type_check CHECK (((capability_type)::text = ANY (ARRAY[('native'::character varying)::text, ('model_native'::character varying)::text, ('mcp'::character varying)::text, ('skill'::character varying)::text, ('connector'::character varying)::text, ('knowledge'::character varying)::text]))),
    CONSTRAINT agent_version_capabilities_schema_hash_check CHECK (((schema_hash IS NULL) OR (schema_hash ~ '^[0-9a-f]{64}$'::text)))
);

CREATE TABLE gateway.agent_version_knowledge_bindings (
    tenant_id character varying(255) NOT NULL,
    agent_version_id uuid NOT NULL,
    dataset_id character varying(255) NOT NULL,
    retrieval_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    bound_by character varying(255),
    authorization_checked_at timestamp with time zone,
    content_mode character varying(32) DEFAULT 'live_latest'::character varying NOT NULL,
    historical_replayable boolean DEFAULT false NOT NULL,
    CONSTRAINT agent_version_knowledge_live_content_check CHECK ((((content_mode)::text = 'live_latest'::text) AND (historical_replayable = false)))
);

CREATE TABLE gateway.agent_version_revocations (
    tenant_id character varying(255) NOT NULL,
    agent_version_id uuid NOT NULL,
    revoked_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_by character varying(255) NOT NULL,
    reason text DEFAULT ''::text NOT NULL
);

CREATE TABLE gateway.agent_version_skill_bindings (
    tenant_id character varying(255) NOT NULL,
    agent_version_id uuid NOT NULL,
    skill_id uuid NOT NULL,
    skill_version_id uuid NOT NULL,
    skill_name character varying(128) NOT NULL,
    content_hash character(64) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_version_skill_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE gateway.agent_versions (
    tenant_id character varying(255) NOT NULL,
    agent_version_id uuid DEFAULT gen_random_uuid() NOT NULL,
    agent_id uuid NOT NULL,
    version_number integer NOT NULL,
    schema_version character varying(64) DEFAULT 'agent-spec/v1'::character varying NOT NULL,
    resolved_spec jsonb NOT NULL,
    spec_hash character(64) NOT NULL,
    source_draft_id uuid NOT NULL,
    source_draft_revision integer NOT NULL,
    bindings_sealed boolean DEFAULT false NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    release_evaluation_id uuid,
    release_identity_hash character(64),
    CONSTRAINT agent_versions_release_identity_hash_check CHECK (((release_identity_hash IS NULL) OR (release_identity_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT agent_versions_source_draft_revision_check CHECK ((source_draft_revision >= 1)),
    CONSTRAINT agent_versions_spec_hash_check CHECK ((spec_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_versions_version_number_check CHECK ((version_number >= 1))
);

CREATE TABLE gateway.agents (
    tenant_id character varying(255) NOT NULL,
    agent_id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug character varying(128) NOT NULL,
    name character varying(255) NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    owner_id character varying(255) NOT NULL,
    status character varying(32) DEFAULT 'draft'::character varying NOT NULL,
    current_draft_id uuid,
    archived_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_by character varying(255) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agents_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('active'::character varying)::text, ('archived'::character varying)::text, ('deleted'::character varying)::text])))
);

CREATE TABLE gateway.api_keys (
    id integer NOT NULL,
    key_hash character varying(255) NOT NULL,
    name character varying(255),
    description text,
    tenant_id character varying(255),
    user_id character varying(255),
    roles character varying(50)[] DEFAULT ARRAY['user'::character varying(50)] NOT NULL,
    permissions character varying(100)[] DEFAULT (ARRAY[]::character varying[])::character varying(100)[] NOT NULL,
    tier character varying(50) DEFAULT 'normal'::character varying NOT NULL,
    rate_limit jsonb,
    allowed_services character varying(255)[] DEFAULT (ARRAY[]::character varying[])::character varying(255)[] NOT NULL,
    allowed_models character varying(255)[] DEFAULT (ARRAY[]::character varying[])::character varying(255)[] NOT NULL,
    expires_at timestamp with time zone,
    enabled boolean DEFAULT true NOT NULL,
    last_used_at timestamp with time zone,
    use_count bigint DEFAULT 0 NOT NULL,
    key_id character varying(32),
    key_prefix character varying(12),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scopes text[] DEFAULT ARRAY['knowledge:read'::text, 'knowledge:write'::text],
    CONSTRAINT api_keys_use_count_check CHECK ((use_count >= 0))
);

CREATE SEQUENCE gateway.api_keys_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE gateway.api_keys_id_seq OWNED BY gateway.api_keys.id;

CREATE TABLE gateway.audit_logs (
    id bigint NOT NULL,
    event_type character varying(100) NOT NULL,
    user_id character varying(255),
    tenant_id character varying(255),
    ip_address character varying(45),
    user_agent text,
    resource_type character varying(100),
    resource_id character varying(255),
    action character varying(50) NOT NULL,
    request_summary jsonb,
    response_summary jsonb,
    status character varying(50) NOT NULL,
    error_message text,
    duration_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_id uuid,
    agent_version_id uuid,
    publication_id uuid,
    channel character varying(16),
    redaction_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT audit_logs_agent_channel_check CHECK (((channel IS NULL) OR ((channel)::text = ANY (ARRAY[('preview'::character varying)::text, ('hosted'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text, ('builtin'::character varying)::text])))),
    CONSTRAINT audit_logs_duration_ms_check CHECK (((duration_ms IS NULL) OR (duration_ms >= 0)))
);

CREATE SEQUENCE gateway.audit_logs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE gateway.audit_logs_id_seq OWNED BY gateway.audit_logs.id;

CREATE TABLE gateway.auth_config (
    id integer NOT NULL,
    config_type character varying(50) NOT NULL,
    config jsonb NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE gateway.auth_config_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE gateway.auth_config_id_seq OWNED BY gateway.auth_config.id;

CREATE TABLE gateway.billing_events (
    id bigint NOT NULL,
    event_id character varying(255) NOT NULL,
    request_id character varying(255) NOT NULL,
    service_id character varying(255) NOT NULL,
    user_id character varying(255),
    tenant_id character varying(255),
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    total_tokens integer DEFAULT 0 NOT NULL,
    model character varying(255),
    assistant_id character varying(255),
    duration_ms numeric(12,2),
    status character varying(50) DEFAULT 'completed'::character varying NOT NULL,
    cost_amount numeric(12,6),
    cost_currency character varying(10) DEFAULT 'USD'::character varying,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    event_time timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_events_duration_ms_check CHECK (((duration_ms IS NULL) OR (duration_ms >= (0)::numeric))),
    CONSTRAINT billing_events_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT billing_events_output_tokens_check CHECK ((output_tokens >= 0)),
    CONSTRAINT billing_events_total_tokens_check CHECK ((total_tokens >= 0))
);

CREATE SEQUENCE gateway.billing_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE gateway.billing_events_id_seq OWNED BY gateway.billing_events.id;

CREATE TABLE gateway.connector_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id character varying(64) DEFAULT ''::character varying NOT NULL,
    provider character varying(64) NOT NULL,
    display_name character varying(256) NOT NULL,
    description text,
    icon_url character varying(512),
    client_id text NOT NULL,
    client_secret text,
    auth_url text NOT NULL,
    token_url text NOT NULL,
    scopes text NOT NULL,
    redirect_uri text,
    enabled boolean DEFAULT true,
    supports_sync boolean DEFAULT false,
    supports_search boolean DEFAULT true,
    extra_config jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    mode character varying(16) DEFAULT 'live'::character varying NOT NULL,
    CONSTRAINT connector_configs_mode_check CHECK (((mode)::text = ANY (ARRAY[('live'::character varying)::text, ('ingest'::character varying)::text, ('both'::character varying)::text])))
);

CREATE TABLE gateway.connector_credential_principals (
    tenant_id character varying(255) NOT NULL,
    grant_id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider character varying(64) NOT NULL,
    principal_type character varying(32) NOT NULL,
    owner_user_id character varying(255),
    secret_ref text NOT NULL,
    scopes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    audience text,
    connection_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    allowed_channels text[] DEFAULT ARRAY['preview'::text, 'hosted_private'::text] NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    enabled boolean DEFAULT true NOT NULL,
    created_by character varying(255) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT connector_credential_principals_channels_check CHECK ((allowed_channels <@ ARRAY['preview'::text, 'hosted_private'::text, 'hosted_public'::text, 'embed'::text, 'api'::text])),
    CONSTRAINT connector_credential_principals_owner_check CHECK (((((principal_type)::text = 'service_account'::text) AND (owner_user_id IS NULL)) OR (((principal_type)::text = 'user_delegated'::text) AND (owner_user_id IS NOT NULL)))),
    CONSTRAINT connector_credential_principals_principal_type_check CHECK (((principal_type)::text = ANY (ARRAY[('service_account'::character varying)::text, ('user_delegated'::character varying)::text]))),
    CONSTRAINT connector_credential_principals_provider_check CHECK (((provider)::text = 'confluence'::text)),
    CONSTRAINT connector_credential_principals_secret_ref_check CHECK (((secret_ref ~ '^[a-z][a-z0-9+.-]*://[^[:space:]]+$'::text) AND (secret_ref !~ '^https?://'::text)))
);

CREATE TABLE gateway.email_domain_config (
    id integer NOT NULL,
    domain character varying(255) NOT NULL,
