    CONSTRAINT chk_eval_evaluators_type CHECK (((evaluator_type)::text = ANY (ARRAY[('human'::character varying)::text, ('rule'::character varying)::text, ('trajectory'::character varying)::text, ('span'::character varying)::text, ('llm'::character varying)::text, ('llm_judge'::character varying)::text, ('composite'::character varying)::text, ('ragas'::character varying)::text])))
);

CREATE TABLE gateway.eval_examples (
