);

CREATE TABLE gateway.eval_experiment_run_cases (
    run_case_id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    tenant_id character varying(64) NOT NULL,
    case_id character varying(160) NOT NULL,
    example_id uuid,
    trial_index integer DEFAULT 1 NOT NULL,
    status character varying(32) DEFAULT 'queued'::character varying NOT NULL,
    input jsonb DEFAULT '{}'::jsonb NOT NULL,
    expected_output jsonb DEFAULT '{}'::jsonb NOT NULL,
    expected_trajectory jsonb DEFAULT '{}'::jsonb NOT NULL,
    assertions jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    candidate_trace_id uuid,
    observed_metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT eval_experiment_run_cases_status_check CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('skipped'::character varying)::text]))),
    CONSTRAINT eval_experiment_run_cases_trial_index_check CHECK (((trial_index >= 1) AND (trial_index <= 10)))
);

CREATE TABLE gateway.eval_experiment_runs (
    run_id uuid DEFAULT gen_random_uuid() NOT NULL,
    experiment_id uuid,
    tenant_id character varying(64) NOT NULL,
    evaluator_id uuid,
    dataset_id uuid,
    status character varying(32) DEFAULT 'queued'::character varying NOT NULL,
    target_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    score_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text,
    created_by character varying(64) NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    run_mode character varying(32) DEFAULT 'rescore_trace'::character varying NOT NULL,
    repetitions integer DEFAULT 1 NOT NULL,
    baseline_run_id uuid,
    dataset_manifest_hash character varying(64),
    evaluator_suite_hash character varying(64),
    candidate_fingerprint jsonb DEFAULT '{}'::jsonb NOT NULL,
    execution_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_eval_experiment_runs_mode CHECK (((run_mode)::text = ANY (ARRAY[('rescore_trace'::character varying)::text, ('live_candidate'::character varying)::text]))),
    CONSTRAINT chk_eval_experiment_runs_repetitions CHECK (((repetitions >= 1) AND (repetitions <= 10))),
    CONSTRAINT chk_eval_experiment_runs_status CHECK (((status)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text])))
);

CREATE TABLE gateway.eval_experiments (
