CREATE TABLE gateway.llm_models (
    tenant_id character varying(100) NOT NULL,
    model_id character varying(100) NOT NULL,
    provider_id character varying(50) NOT NULL,
    display_name character varying(100) NOT NULL,
    context_window integer DEFAULT 128000,
    max_output_tokens integer DEFAULT 4096,
    supports_vision boolean DEFAULT false,
    supports_tools boolean DEFAULT true,
    input_price_per_1k numeric(10,6) DEFAULT 0,
    output_price_per_1k numeric(10,6) DEFAULT 0,
    access_level character varying(20) DEFAULT 'public'::character varying,
    is_enabled boolean DEFAULT true,
    sort_order integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    catalog_capabilities jsonb DEFAULT '{}'::jsonb NOT NULL,
    capability_overrides jsonb DEFAULT '{}'::jsonb NOT NULL,
    capability_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT llm_models_capability_overrides_object CHECK ((jsonb_typeof(capability_overrides) = 'object'::text)),
    CONSTRAINT llm_models_capability_revision_positive CHECK ((capability_revision > 0)),
    CONSTRAINT llm_models_catalog_capabilities_object CHECK ((jsonb_typeof(catalog_capabilities) = 'object'::text))
);

