    last_seen_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT local_node_channels_receipt_cursor_check CHECK ((receipt_cursor >= 0)),
    CONSTRAINT local_node_channels_status_check CHECK (((status)::text = ANY (ARRAY[('online'::character varying)::text, ('offline'::character varying)::text, ('revoked'::character varying)::text])))
);

