    last_seen_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT local_node_devices_capabilities_check CHECK ((jsonb_typeof(capabilities) = 'array'::text)),
    CONSTRAINT local_node_devices_capability_revision_check CHECK ((capability_revision >= 1)),
    CONSTRAINT local_node_devices_status_check CHECK (((status)::text = ANY (ARRAY[('online'::character varying)::text, ('offline'::character varying)::text, ('stale'::character varying)::text, ('revoked'::character varying)::text])))
);

