CREATE TABLE gateway.local_node_executions (
    execution_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    tenant_id character varying(128) NOT NULL,
    user_id character varying(128) NOT NULL,
    session_id character varying(255) NOT NULL,
    run_id uuid NOT NULL,
    tool_call_id character varying(255) NOT NULL,
    attempt_id character varying(255) NOT NULL,
    device_id character varying(255) NOT NULL,
    channel_id character varying(255) NOT NULL,
    grant_id uuid,
    grant_revision bigint,
    capability_id character varying(255) NOT NULL,
    capability_revision bigint NOT NULL,
    operation character varying(255) NOT NULL,
    arguments jsonb NOT NULL,
    arguments_sha256 character(64) NOT NULL,
    idempotency_key character varying(255) NOT NULL,
    effect character varying(16) NOT NULL,
    approval_id uuid,
    approval_status character varying(16) DEFAULT 'not_required'::character varying NOT NULL,
    resource_binding jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(32) DEFAULT 'published'::character varying NOT NULL,
    dispatch_fence uuid,
    dispatched_at timestamp with time zone,
    receipt_cursor bigint DEFAULT 0 NOT NULL,
    result_summary jsonb,
    terminal_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT local_node_executions_approval_status_check CHECK (((approval_status)::text = ANY (ARRAY[('not_required'::character varying)::text, ('pending'::character varying)::text, ('approved'::character varying)::text, ('consumed'::character varying)::text, ('denied'::character varying)::text, ('expired'::character varying)::text]))),
    CONSTRAINT local_node_executions_arguments_check CHECK ((jsonb_typeof(arguments) = 'object'::text)),
    CONSTRAINT local_node_executions_arguments_sha256_check CHECK ((arguments_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT local_node_executions_capability_revision_check CHECK ((capability_revision >= 1)),
    CONSTRAINT local_node_executions_check CHECK (((((effect)::text = 'read'::text) AND (approval_id IS NULL) AND ((approval_status)::text = 'not_required'::text)) OR (((effect)::text = ANY (ARRAY[('write'::character varying)::text, ('unknown'::character varying)::text])) AND (approval_id IS NOT NULL) AND ((approval_status)::text <> 'not_required'::text)))),
    CONSTRAINT local_node_executions_effect_check CHECK (((effect)::text = ANY (ARRAY[('read'::character varying)::text, ('write'::character varying)::text, ('unknown'::character varying)::text]))),
    CONSTRAINT local_node_executions_receipt_cursor_check CHECK ((receipt_cursor >= 0)),
    CONSTRAINT local_node_executions_resource_binding_check CHECK ((jsonb_typeof(resource_binding) = 'object'::text)),
    CONSTRAINT local_node_executions_status_check CHECK (((status)::text = ANY (ARRAY[('published'::character varying)::text, ('awaiting_approval'::character varying)::text, ('dispatched'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('timeout'::character varying)::text, ('side_effect_unknown'::character varying)::text])))
);

