    CONSTRAINT mcp_channel_grants_channel_check CHECK (((channel)::text = ANY (ARRAY[('preview'::character varying)::text, ('hosted_private'::character varying)::text, ('hosted_public'::character varying)::text, ('embed'::character varying)::text, ('api'::character varying)::text])))
);

CREATE TABLE gateway.mcp_connections (
    tenant_id character varying(255) NOT NULL,
    connection_id uuid DEFAULT gen_random_uuid() NOT NULL,
    server_id uuid NOT NULL,
    principal_type character varying(32) NOT NULL,
    owner_user_id character varying(255),
    secret_ref text,
    scopes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    audience text,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    enabled boolean DEFAULT true NOT NULL,
    created_by character varying(255) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mcp_connections_principal_owner_check CHECK (((((principal_type)::text = 'service_account'::text) AND (owner_user_id IS NULL)) OR (((principal_type)::text = 'user_delegated'::text) AND (owner_user_id IS NOT NULL)))),
    CONSTRAINT mcp_connections_principal_type_check CHECK (((principal_type)::text = ANY (ARRAY[('service_account'::character varying)::text, ('user_delegated'::character varying)::text]))),
    CONSTRAINT mcp_connections_secret_ref_check CHECK (((secret_ref IS NULL) OR ((secret_ref ~ '^[a-z][a-z0-9+.-]*://[^[:space:]]+$'::text) AND (secret_ref !~ '^https?://'::text))))
);

