CREATE TABLE gateway.mcp_servers (
    tenant_id character varying(255) NOT NULL,
    server_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(128) NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    base_url text NOT NULL,
    transport character varying(32) DEFAULT 'streamable_http'::character varying NOT NULL,
    auth_method character varying(32) DEFAULT 'none'::character varying NOT NULL,
    oauth_metadata_url text,
    oauth_resource text,
    oauth_audience text,
    allowed_origins text[] DEFAULT ARRAY[]::text[] NOT NULL,
    timeout_ms integer DEFAULT 30000 NOT NULL,
    max_concurrency integer DEFAULT 5 NOT NULL,
    response_limit_bytes integer DEFAULT 1048576 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    health_status character varying(32) DEFAULT 'unknown'::character varying NOT NULL,
    circuit_state character varying(16) DEFAULT 'closed'::character varying NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    circuit_open_until timestamp with time zone,
    last_health_at timestamp with time zone,
    last_error_code character varying(64),
    deleted_at timestamp with time zone,
    created_by character varying(255) NOT NULL,
    updated_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mcp_servers_allowed_origins_check CHECK (((cardinality(allowed_origins) >= 1) AND (cardinality(allowed_origins) <= 64))),
    CONSTRAINT mcp_servers_auth_method_check CHECK (((auth_method)::text = ANY (ARRAY[('none'::character varying)::text, ('bearer'::character varying)::text, ('oauth'::character varying)::text]))),
    CONSTRAINT mcp_servers_circuit_state_check CHECK (((circuit_state)::text = ANY (ARRAY[('closed'::character varying)::text, ('open'::character varying)::text, ('half_open'::character varying)::text]))),
    CONSTRAINT mcp_servers_consecutive_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT mcp_servers_health_status_check CHECK (((health_status)::text = ANY (ARRAY[('unknown'::character varying)::text, ('healthy'::character varying)::text, ('degraded'::character varying)::text, ('unavailable'::character varying)::text]))),
    CONSTRAINT mcp_servers_https_url_check CHECK (((base_url ~ '^https://[^[:space:]]+$'::text) AND (base_url !~ '@'::text))),
    CONSTRAINT mcp_servers_max_concurrency_check CHECK (((max_concurrency >= 1) AND (max_concurrency <= 32))),
    CONSTRAINT mcp_servers_response_limit_bytes_check CHECK (((response_limit_bytes >= 1024) AND (response_limit_bytes <= 8388608))),
    CONSTRAINT mcp_servers_timeout_ms_check CHECK (((timeout_ms >= 100) AND (timeout_ms <= 120000))),
    CONSTRAINT mcp_servers_transport_check CHECK (((transport)::text = 'streamable_http'::text))
);

