    CONSTRAINT usage_statistics_max_response_time_ms_check CHECK (((max_response_time_ms IS NULL) OR (max_response_time_ms >= 0))),
    CONSTRAINT usage_statistics_min_response_time_ms_check CHECK (((min_response_time_ms IS NULL) OR (min_response_time_ms >= 0))),
    CONSTRAINT usage_statistics_output_tokens_check CHECK ((output_tokens >= 0)),
    CONSTRAINT usage_statistics_request_count_check CHECK ((request_count >= 0)),
    CONSTRAINT usage_statistics_success_count_check CHECK ((success_count >= 0))
);

