CREATE VIEW gateway.v_active_proxy_services AS
 SELECT service_id,
    name,
    description,
    (connector_config ->> 'upstream_url'::text) AS upstream_url,
    (connector_config ->> 'assistant_id'::text) AS assistant_id,
    (connector_config ->> 'load_balance_strategy'::text) AS load_balance_strategy,
    ((connector_config ->> 'timeout_read'::text))::integer AS timeout_read,
    status,
    created_at,
    updated_at
   FROM gateway.services
  WHERE (((status)::text = 'active'::text) AND ((connector_config ->> 'proxy_mode'::text) = 'transparent'::text));

CREATE VIEW gateway.v_user_billing_summary AS
 SELECT user_id,
    tenant_id,
    date_trunc('day'::text, event_time) AS billing_date,
    count(*) AS request_count,
    sum(input_tokens) AS total_input_tokens,
    sum(output_tokens) AS total_output_tokens,
    sum(total_tokens) AS total_tokens,
    sum(cost_amount) AS total_cost,
    avg(duration_ms) AS avg_duration_ms
   FROM gateway.billing_events
  WHERE ((status)::text = 'completed'::text)
  GROUP BY user_id, tenant_id, (date_trunc('day'::text, event_time));

