    CONSTRAINT chk_dataset_queries_observation_shape CHECK (((trace_id IS NULL) OR (((query_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((mode)::text = ANY (ARRAY[('dense'::character varying)::text, ('bm25'::character varying)::text, ('hybrid'::character varying)::text, ('keyword'::character varying)::text, ('vector'::character varying)::text])) AND ((top_k >= 1) AND (top_k <= 100)) AND (hit_count >= 0) AND (jsonb_typeof(stage_timings) = 'object'::text))))
);

