    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_dataset_query_feedback_reason CHECK (((((rating)::text = 'positive'::text) AND ((reason_code)::text = ANY (ARRAY[('relevant'::character varying)::text, ('helpful'::character varying)::text, ('well_cited'::character varying)::text, ('other'::character varying)::text]))) OR (((rating)::text = 'negative'::text) AND ((reason_code)::text = ANY (ARRAY[('irrelevant'::character varying)::text, ('incorrect'::character varying)::text, ('missing_context'::character varying)::text, ('bad_citation'::character varying)::text, ('stale'::character varying)::text, ('unsafe'::character varying)::text, ('other'::character varying)::text]))))),
    CONSTRAINT chk_dataset_query_feedback_target CHECK (((((target_type)::text = 'qa_answer'::text) AND ((target_id)::text = (trace_id)::text)) OR (((target_type)::text = 'retrieval_hit'::text) AND ((target_id)::text <> (trace_id)::text)))),
    CONSTRAINT dataset_query_feedback_comment_check CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
    CONSTRAINT dataset_query_feedback_query_fingerprint_check CHECK (((query_fingerprint)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT dataset_query_feedback_rating_check CHECK (((rating)::text = ANY (ARRAY[('positive'::character varying)::text, ('negative'::character varying)::text]))),
    CONSTRAINT dataset_query_feedback_target_id_check CHECK ((length(btrim((target_id)::text)) > 0)),
    CONSTRAINT dataset_query_feedback_target_type_check CHECK (((target_type)::text = ANY (ARRAY[('retrieval_hit'::character varying)::text, ('qa_answer'::character varying)::text])))
);

