    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_expires_at timestamp with time zone,
    last_heartbeat_at timestamp with time zone,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_kb_embedding_action_claim_shape CHECK (((((state)::text = 'running'::text) AND (claim_token IS NOT NULL) AND (claimed_by IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR (((state)::text <> 'running'::text) AND (claim_token IS NULL) AND (claimed_by IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT chk_kb_embedding_action_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT chk_kb_embedding_action_result_object CHECK (((result IS NULL) OR (jsonb_typeof(result) = 'object'::text))),
    CONSTRAINT embedding_migration_action_jobs_action_check CHECK (((action)::text = ANY (ARRAY[('backfill'::character varying)::text, ('verify'::character varying)::text, ('gate'::character varying)::text]))),
    CONSTRAINT embedding_migration_action_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT embedding_migration_action_jobs_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT embedding_migration_action_jobs_state_check CHECK (((state)::text = ANY (ARRAY[('queued'::character varying)::text, ('running'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text])))
);

