CREATE TABLE knowledge.embedding_migrations (
    migration_id uuid DEFAULT gen_random_uuid() NOT NULL,
    dataset_id character varying(255) NOT NULL,
    source_binding_id uuid,
    target_binding_id uuid NOT NULL,
    state character varying(20) DEFAULT 'shadow_build'::character varying NOT NULL,
    checkpoint jsonb DEFAULT '{}'::jsonb NOT NULL,
    totals jsonb DEFAULT '{}'::jsonb NOT NULL,
    gate jsonb,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_kb_embedding_distinct_bindings CHECK (((source_binding_id IS NULL) OR (source_binding_id <> target_binding_id))),
    CONSTRAINT embedding_migrations_state_check CHECK (((state)::text = ANY (ARRAY[('shadow_build'::character varying)::text, ('backfilling'::character varying)::text, ('verified'::character varying)::text, ('gating'::character varying)::text, ('gate_failed'::character varying)::text, ('ready'::character varying)::text, ('completed'::character varying)::text, ('rolled_back'::character varying)::text, ('failed'::character varying)::text, ('abandoned'::character varying)::text])))
);

