);

CREATE TABLE knowledge.kb_bm25_v2_lifecycle (
    dataset_id character varying(255) NOT NULL,
    tenant_id character varying(255) NOT NULL,
    state character varying(32) DEFAULT 'shadow'::character varying NOT NULL,
    epoch bigint DEFAULT 0 NOT NULL,
    transition_kind character varying(16),
    lock_token character varying(64),
    authority_content_revision bigint,
    manifest_sha256 character varying(80) DEFAULT ''::character varying NOT NULL,
    pre_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    post_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT kb_bm25_v2_lifecycle_state_check CHECK (((state)::text = ANY (ARRAY[('shadow'::character varying)::text, ('cutover_in_progress'::character varying)::text, ('active_v2'::character varying)::text, ('rollback_in_progress'::character varying)::text]))),
    CONSTRAINT kb_bm25_v2_lifecycle_transition_kind_check CHECK (((transition_kind)::text = ANY (ARRAY[('cutover'::character varying)::text, ('rollback'::character varying)::text]))),
    CONSTRAINT kb_bm25_v2_lifecycle_transition_shape CHECK (((((state)::text = ANY (ARRAY[('cutover_in_progress'::character varying)::text, ('rollback_in_progress'::character varying)::text])) AND (transition_kind IS NOT NULL) AND (lock_token IS NOT NULL) AND (epoch > 0)) OR (((state)::text = ANY (ARRAY[('shadow'::character varying)::text, ('active_v2'::character varying)::text])) AND (transition_kind IS NULL) AND (lock_token IS NULL))))
);

