    CONSTRAINT kb_document_batch_items_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('claiming'::character varying)::text, ('queued'::character varying)::text, ('skipped'::character varying)::text, ('failed'::character varying)::text])))
);

CREATE TABLE knowledge.kb_document_batch_operations (
    operation_id uuid NOT NULL,
    tenant_id character varying(255) NOT NULL,
    dataset_id character varying(255) NOT NULL,
    operation character varying(32) NOT NULL,
    status character varying(24) DEFAULT 'pending'::character varying NOT NULL,
    total_count integer DEFAULT 0 NOT NULL,
    queued_count integer DEFAULT 0 NOT NULL,
    skipped_count integer DEFAULT 0 NOT NULL,
    failed_count integer DEFAULT 0 NOT NULL,
    created_by character varying(255) NOT NULL,
    actor_roles jsonb DEFAULT '[]'::jsonb NOT NULL,
    last_claimed_at timestamp with time zone,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT kb_document_batch_count_bounds CHECK ((((queued_count + skipped_count) + failed_count) <= total_count)),
    CONSTRAINT kb_document_batch_operations_actor_roles_check CHECK ((jsonb_typeof(actor_roles) = 'array'::text)),
    CONSTRAINT kb_document_batch_operations_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT kb_document_batch_operations_operation_check CHECK (((operation)::text = ANY (ARRAY[('reembed'::character varying)::text, ('delete'::character varying)::text]))),
    CONSTRAINT kb_document_batch_operations_queued_count_check CHECK ((queued_count >= 0)),
    CONSTRAINT kb_document_batch_operations_skipped_count_check CHECK ((skipped_count >= 0)),
    CONSTRAINT kb_document_batch_operations_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('running'::character varying)::text, ('completed'::character varying)::text, ('partial'::character varying)::text, ('failed'::character varying)::text]))),
    CONSTRAINT kb_document_batch_operations_total_count_check CHECK ((total_count >= 0))
);

